option.value:
:root {
  --bg: #070b14;
  --bg-soft: #0d1320;
  --bg-card: rgba(16, 23, 38, 0.88);
  --bg-card-strong: #11192a;
  --text: #eff4ff;
  --text-soft: #c1cadb;
  --text-muted: #7f8aa3;
  --border: rgba(130, 152, 194, 0.18);
  --border-strong: rgba(0, 245, 212, 0.32);
  --cyan: #00f5d4;
  --violet: #9c8cff;
  --rose: #ff7b8d;
  --gold: #ffd166;
  --green: #44d7a8;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.36);
  --radius: 24px;
  --radius-small: 14px;
  --nav-height: 74px;
  --max-width: 1180px;
  --hero-gradient: linear-gradient(160deg, #101833 0%, #060913 52%, #0a1020 100%);
  --accent-gradient: linear-gradient(135deg, #00f5d4 0%, #9c8cff 56%, #ff7b8d 100%);
  --card-gradient: linear-gradient(135deg, rgba(0, 245, 212, 0.12), rgba(156, 140, 255, 0.08));
  --font-body: "Segoe UI", Arial, sans-serif;
  --tilt-x: 0deg;
  --tilt-y: 0deg;
  --bg-orb-1: rgba(0, 245, 212, 0.08);
  --bg-orb-2: rgba(156, 140, 255, 0.08);
  --surface-overlay: rgba(255, 255, 255, 0.04);
  --surface-overlay-strong: rgba(255, 255, 255, 0.06);
  --surface-outline: rgba(255, 255, 255, 0.12);
  --header-bg: rgba(7, 11, 20, 0.78);
  --header-bg-scrolled: rgba(7, 11, 20, 0.92);
  --title-gradient: linear-gradient(135deg, #ffffff 0%, #dce8ff 45%, #ffffff 100%);
  --hero-dot: rgba(255, 255, 255, 0.12);
  --hero-ring: rgba(255, 255, 255, 0.14);
  --shine-overlay: rgba(255, 255, 255, 0.22);
  --mobile-menu-bg: rgba(10, 15, 25, 0.96);
  --nav-link-hover-bg: rgba(255, 255, 255, 0.05);
  --footer-bg: linear-gradient(180deg, #090c18 0%, #04060e 100%);
  --footer-grid: rgba(255, 255, 255, 0.03);
  color-scheme: dark;
}

html[data-theme="light"] {
  --bg: #eef4fb;
  --bg-soft: #dfe9f6;
  --bg-card: rgba(255, 255, 255, 0.82);
  --bg-card-strong: #ffffff;
  --text: #132238;
  --text-soft: #314155;
  --text-muted: #64748b;
  --border: rgba(15, 23, 42, 0.12);
  --border-strong: rgba(0, 184, 162, 0.26);
  --cyan: #6d63ff;
  --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
  --hero-gradient: linear-gradient(160deg, #fbfdff 0%, #e9f2ff 52%, #f5f8fc 100%);
  --accent-gradient: linear-gradient(135deg, #00b8a2 0%, #6d63ff 56%, #ff5f7a 100%);
  --card-gradient: linear-gradient(135deg, rgba(0, 184, 162, 0.12), rgba(109, 99, 255, 0.08));
  --bg-orb-1: rgba(0, 184, 162, 0.12);
  --bg-orb-2: rgba(109, 99, 255, 0.12);
  --surface-overlay: rgba(15, 23, 42, 0.04);
  --surface-overlay-strong: rgba(15, 23, 42, 0.06);
  --surface-outline: rgba(15, 23, 42, 0.1);
  --header-bg: rgba(238, 244, 251, 0.82);
  --header-bg-scrolled: rgba(238, 244, 251, 0.96);
  --title-gradient: linear-gradient(135deg, #11223a 0%, #2f5f98 45%, #11223a 100%);
  --hero-dot: rgba(15, 23, 42, 0.08);
  --hero-ring: rgba(15, 23, 42, 0.12);
  --shine-overlay: rgba(255, 255, 255, 0.32);
  --mobile-menu-bg: rgba(255, 255, 255, 0.96);
  --nav-link-hover-bg: rgba(15, 23, 42, 0.06);
  --footer-bg: linear-gradient(180deg, #e9f1fb 0%, #dde8f8 100%);
  --footer-grid: rgba(15, 23, 42, 0.05);
  color-scheme: light;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  position: relative;
  font-family: var(--font-body);
  color: var(--text);
  background:
    radial-gradient(circle at top right, var(--bg-orb-1), transparent 28%),
    radial-gradient(circle at bottom left, var(--bg-orb-2), transparent 30%),
    var(--bg);
  line-height: 1.65;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 0.55s ease, transform 0.55s ease, background-color 0.3s ease, color 0.3s ease;
}

body::before,
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  z-index: 420;
}

body::before {
  background:
    radial-gradient(circle at 18% 26%, rgba(0, 245, 212, 0.24), transparent 28%),
    radial-gradient(circle at 78% 34%, rgba(156, 140, 255, 0.22), transparent 26%),
    radial-gradient(circle at 52% 74%, rgba(255, 123, 141, 0.18), transparent 24%),
    linear-gradient(115deg, transparent 30%, rgba(0, 245, 212, 0.08) 48%, transparent 66%);
  mix-blend-mode: screen;
  filter: blur(32px);
}

body::after {
  background:
    linear-gradient(90deg, transparent 0%, rgba(0, 245, 212, 0.14) 18%, transparent 36%),
    linear-gradient(90deg, transparent 26%, rgba(156, 140, 255, 0.1) 50%, transparent 74%),
    linear-gradient(90deg, transparent 58%, rgba(255, 123, 141, 0.1) 82%, transparent 100%);
}

body.is-theme-shifting::before {
  animation: themeMorphGlow 720ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

body.is-theme-shifting::after {
  animation: themeMorphSlices 680ms steps(2, end) both;
}

body.is-page-leaving::before,
body.is-page-arriving::before {
  animation: themeMorphGlow 760ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

body.is-page-leaving::after,
body.is-page-arriving::after {
  animation: pageMorphSlices 720ms steps(2, end) both;
}

body.is-theme-shifting .site-header,
body.is-theme-shifting .page-main,
body.is-theme-shifting .hero,
body.is-theme-shifting .footer {
  animation: themeSurfaceMorph 680ms cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: center;
  will-change: transform, filter, clip-path, opacity;
}

body.is-page-leaving {
  overflow: hidden;
}

body.is-page-leaving .site-header,
body.is-page-leaving .page-main,
body.is-page-leaving .hero,
body.is-page-leaving .footer {
  animation: pageGlitchOut 520ms cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: center;
  will-change: transform, filter, clip-path, opacity;
}

body.is-page-arriving .site-header,
body.is-page-arriving .page-main,
body.is-page-arriving .hero,
body.is-page-arriving .footer {
  animation: pageGlitchIn 760ms cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: center;
  will-change: transform, filter, clip-path, opacity;
}

@keyframes themeMorphGlow {
  0% {
    opacity: 0;
    transform: scale(0.96);
  }
  18% {
    opacity: 0.5;
    transform: scale(1.02) translate3d(-8px, 0, 0);
  }
  44% {
    opacity: 0.75;
    transform: scale(1.05) translate3d(10px, -4px, 0);
  }
  72% {
    opacity: 0.28;
    transform: scale(1.01) translate3d(-4px, 3px, 0);
  }
  100% {
    opacity: 0;
    transform: scale(1.08);
  }
}

@keyframes themeMorphSlices {
  0% {
    opacity: 0;
    clip-path: inset(0 0 100% 0);
    transform: translate3d(0, 0, 0);
  }
  24% {
    opacity: 0.45;
    clip-path: inset(8% 0 56% 0);
    transform: translate3d(-10px, 0, 0);
  }
  48% {
    opacity: 0.38;
    clip-path: inset(38% 0 18% 0);
    transform: translate3d(12px, 0, 0);
  }
  72% {
    opacity: 0.22;
    clip-path: inset(70% 0 8% 0);
    transform: translate3d(-8px, 0, 0);
  }
  100% {
    opacity: 0;
    clip-path: inset(100% 0 0 0);
    transform: translate3d(0, 0, 0);
  }
}

@keyframes pageMorphSlices {
  0% {
    opacity: 0;
    clip-path: inset(0 0 100% 0);
    transform: translate3d(0, 0, 0);
  }
  18% {
    opacity: 0.55;
    clip-path: inset(6% 0 68% 0);
    transform: translate3d(-14px, 0, 0);
  }
  40% {
    opacity: 0.44;
    clip-path: inset(28% 0 36% 0);
    transform: translate3d(16px, 0, 0);
  }
  62% {
    opacity: 0.34;
    clip-path: inset(56% 0 18% 0);
    transform: translate3d(-10px, 0, 0);
  }
  84% {
    opacity: 0.18;
    clip-path: inset(82% 0 6% 0);
    transform: translate3d(8px, 0, 0);
  }
  100% {
    opacity: 0;
    clip-path: inset(100% 0 0 0);
    transform: translate3d(0, 0, 0);
  }
}

@keyframes themeSurfaceMorph {
  0% {
    filter: saturate(1) blur(0);
    clip-path: inset(0 0 0 0 round 0);
    transform: translate3d(0, 0, 0) scale(1);
  }
  18% {
    filter: saturate(1.18) blur(1px);
    clip-path: inset(0.5% 0 1.2% 0 round 18px);
    transform: translate3d(-4px, 1px, 0) scale(1.003);
  }
  42% {
    filter: saturate(1.08) blur(1.8px);
    clip-path: inset(1.2% 0 0.4% 0 round 24px);
    transform: translate3d(5px, -2px, 0) scale(1.008);
  }
  68% {
    filter: saturate(1.02) blur(0.8px);
    clip-path: inset(0.4% 0 0.8% 0 round 16px);
    transform: translate3d(-2px, 1px, 0) scale(1.002);
  }
  100% {
    filter: saturate(1) blur(0);
    clip-path: inset(0 0 0 0 round 0);
    transform: translate3d(0, 0, 0) scale(1);
  }
}

@keyframes pageGlitchOut {
  0% {
    opacity: 1;
    filter: saturate(1) blur(0) drop-shadow(0 0 0 rgba(0, 245, 212, 0)) drop-shadow(0 0 0 rgba(255, 123, 141, 0));
    clip-path: inset(0 0 0 0 round 0);
    transform: translate3d(0, 0, 0) scale(1);
  }
  18% {
    opacity: 0.98;
    filter:
      saturate(1.18)
      blur(0.8px)
      drop-shadow(-4px 0 0 rgba(0, 245, 212, 0.18))
      drop-shadow(3px 0 0 rgba(255, 123, 141, 0.1));
    clip-path: inset(0.4% 0 1.8% 0 round 18px);
    transform: translate3d(-5px, 1px, 0) scale(1.003);
  }
  42% {
    opacity: 0.82;
    filter:
      saturate(1.28)
      blur(1.8px)
      drop-shadow(-8px 0 0 rgba(0, 245, 212, 0.34))
      drop-shadow(6px 0 0 rgba(255, 123, 141, 0.16));
    clip-path: inset(1.2% 0 4.4% 0 round 24px);
    transform: translate3d(8px, -3px, 0) scale(1.012);
  }
  72% {
    opacity: 0.36;
    filter:
      saturate(1.08)
      blur(2.4px)
      drop-shadow(-10px 0 0 rgba(0, 245, 212, 0.24))
      drop-shadow(7px 0 0 rgba(255, 123, 141, 0.12));
    clip-path: inset(6% 0 10% 0 round 32px);
    transform: translate3d(-10px, 3px, 0) scale(1.02);
  }
  100% {
    opacity: 0;
    filter:
      saturate(0.96)
      blur(4px)
      drop-shadow(-14px 0 0 rgba(0, 245, 212, 0.1))
      drop-shadow(10px 0 0 rgba(255, 123, 141, 0.06));
    clip-path: inset(14% 0 18% 0 round 42px);
    transform: translate3d(14px, -4px, 0) scale(1.03);
  }
}

@keyframes pageGlitchIn {
  0% {
    opacity: 0;
    filter:
      saturate(1.3)
      blur(4px)
      drop-shadow(-14px 0 0 rgba(0, 245, 212, 0.28))
      drop-shadow(10px 0 0 rgba(255, 123, 141, 0.14));
    clip-path: inset(16% 0 20% 0 round 42px);
    transform: translate3d(-14px, 5px, 0) scale(1.03);
  }
  24% {
    opacity: 0.42;
    filter:
      saturate(1.22)
      blur(2.4px)
      drop-shadow(-10px 0 0 rgba(0, 245, 212, 0.34))
      drop-shadow(7px 0 0 rgba(255, 123, 141, 0.16));
    clip-path: inset(7% 0 10% 0 round 30px);
    transform: translate3d(10px, -3px, 0) scale(1.018);
  }
  48% {
    opacity: 0.78;
    filter:
      saturate(1.12)
      blur(1.2px)
      drop-shadow(-7px 0 0 rgba(0, 245, 212, 0.26))
      drop-shadow(5px 0 0 rgba(255, 123, 141, 0.12));
    clip-path: inset(2.2% 0 4.2% 0 round 20px);
    transform: translate3d(-6px, 2px, 0) scale(1.008);
  }
  76% {
    opacity: 0.94;
    filter:
      saturate(1.04)
      blur(0.4px)
      drop-shadow(-3px 0 0 rgba(0, 245, 212, 0.12))
      drop-shadow(2px 0 0 rgba(255, 123, 141, 0.08));
    clip-path: inset(0.6% 0 1.2% 0 round 10px);
    transform: translate3d(3px, -1px, 0) scale(1.002);
  }
  100% {
    opacity: 1;
    filter: saturate(1) blur(0) drop-shadow(0 0 0 rgba(0, 245, 212, 0)) drop-shadow(0 0 0 rgba(255, 123, 141, 0));
    clip-path: inset(0 0 0 0 round 0);
    transform: translate3d(0, 0, 0) scale(1);
  }
}

body.is-ready {
  opacity: 1;
  transform: translateY(0);
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

p {
  margin: 0 0 1rem;
  color: var(--text-soft);
}

ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

h1,
h2,
h3,
h4 {
  margin: 0;
  line-height: 1.12;
}

.container {
  width: min(var(--max-width), calc(100% - 2rem));
  margin: 0 auto;
}

.section {
  padding: clamp(4.5rem, 8vw, 7rem) 0;
}

.section-header {
  margin-bottom: 2rem;
  max-width: 700px;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  margin-bottom: 0.9rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--cyan);
  transition: color 0.24s ease, transform 0.24s ease;
}

.eyebrow::before {
  content: "";
  width: 28px;
  height: 2px;
  border-radius: 999px;
  background: var(--accent-gradient);
  transition: transform 0.24s ease, filter 0.24s ease;
}

.eyebrow:hover {
  color: var(--violet);
  transform: translateX(2px);
}

.eyebrow:hover::before {
  transform: scaleX(1.08);
  filter: saturate(1.15) brightness(1.08);
}

.section-header h2 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  letter-spacing: -0.04em;
}

.section-header p {
  margin-top: 0.8rem;
  max-width: 60ch;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
}

.skip-link:focus {
  left: 1rem;
  top: 1rem;
  z-index: 500;
  padding: 0.75rem 1rem;
  border-radius: 10px;
  background: #fff;
  color: #000;
}

.site-header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 300;
  height: var(--nav-height);
  backdrop-filter: blur(18px);
  background: var(--header-bg);
  border-bottom: 1px solid transparent;
  transition: border-color 0.25s ease, background 0.25s ease;
}

.site-header.is-scrolled {
  border-bottom-color: var(--border);
  background: var(--header-bg-scrolled);
}

.nav {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.nav > nav {
  margin-left: auto;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
  font-weight: 700;
  transition: transform 0.22s ease;
}

.brand:hover {
  transform: translateY(-2px);
}

.brand__mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 56px;
  height: 42px;
  padding: 0 0.7rem;
  border-radius: 14px;
  background: var(--surface-overlay);
  border: 1px solid var(--surface-outline);
  background-image: var(--accent-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  font-size: 0.98rem;
  font-weight: 800;
  letter-spacing: -0.05em;
  line-height: 1;
  white-space: nowrap;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}

.brand:hover .brand__mark {
  transform: rotate(-6deg) scale(1.04);
  box-shadow: 0 14px 26px rgba(0, 245, 212, 0.16);
  border-color: rgba(0, 245, 212, 0.24);
}

.brand__text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.brand__name {
  font-size: 0.98rem;
}

.brand__role {
  font-size: 0.74rem;
  color: var(--text-muted);
  font-weight: 500;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.nav__link {
  position: relative;
  font-size: 0.96rem;
  font-weight: 600;
  color: var(--text-soft);
  transition: color 0.2s ease, transform 0.2s ease;
}

.nav__link::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -0.35rem;
  width: 100%;
  height: 2px;
  border-radius: 999px;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.22s ease;
  background: var(--accent-gradient);
}

.nav__link:hover,
.nav__link[aria-current="page"] {
  color: var(--text);
  transform: translateY(-1px);
}

.nav__link:hover::after,
.nav__link[aria-current="page"]::after {
  transform: scaleX(1);
}

.nav__toggle {
  display: none;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface-overlay);
  cursor: pointer;
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex-shrink: 0;
}

.theme-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 34px;
  padding: 0.18rem 0.45rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  opacity: 0.82;
  transition: background 0.2s ease, border-color 0.2s ease, opacity 0.2s ease;
}

.theme-toggle:hover {
  border-color: var(--border);
  background: var(--surface-overlay);
  opacity: 1;
}

.theme-toggle__track {
  position: relative;
  width: 30px;
  height: 16px;
  border-radius: 999px;
  background: var(--surface-overlay);
  box-shadow: inset 0 0 0 1px var(--border);
  overflow: hidden;
  transition: background 0.28s ease, box-shadow 0.28s ease;
}

.theme-toggle__track::before,
.theme-toggle__track::after {
  position: absolute;
  top: 50%;
  font-size: 0.52rem;
  line-height: 1;
  color: var(--text-soft);
  transform: translateY(-50%);
  transition: opacity 0.28s ease, transform 0.32s cubic-bezier(0.22, 1, 0.36, 1), color 0.28s ease;
}

.theme-toggle__track::before {
  content: "\2600";
  left: 3px;
  opacity: 0;
  transform: translateY(-50%) scale(0.78);
}

.theme-toggle__track::after {
  content: "\263E";
  right: 3px;
  opacity: 1;
  transform: translateY(-50%) scale(1);
}

.theme-toggle__thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text);
  box-shadow: none;
  transition: transform 0.32s cubic-bezier(0.22, 1, 0.36, 1), background 0.28s ease;
}

html[data-theme="light"] .theme-toggle__thumb {
  transform: translateX(14px);
  background: var(--violet);
}

.theme-toggle__text {
  display: none;
}

html[data-theme="light"] .theme-toggle__track::before {
  opacity: 1;
  transform: translateY(-50%) scale(1);
  color: var(--violet);
}

html[data-theme="light"] .theme-toggle__track::after {
  opacity: 0;
  transform: translateY(-50%) scale(0.78);
}

.nav__toggle span {
  display: block;
  width: 20px;
  height: 2px;
  margin: 5px auto;
  background: var(--text);
  border-radius: 999px;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

.nav__toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.nav__toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.nav__toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.page-main {
  padding-top: var(--nav-height);
}

.hero {
  position: relative;
  overflow: hidden;
  background: var(--hero-gradient);
}

.hero::before,
.hero::after {
  content: "";
  position: absolute;
  border-radius: 999px;
  filter: blur(80px);
  pointer-events: none;
  animation: heroGlow 14s ease-in-out infinite alternate;
}

.hero__inner::before,
.page-hero__inner::before {
  content: "";
  position: absolute;
  inset: 8% 18% auto auto;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background:
    radial-gradient(circle, var(--hero-dot) 0 4%, transparent 4% 100%),
    radial-gradient(circle, rgba(0, 245, 212, 0.18), transparent 66%);
  opacity: 0.5;
  filter: blur(2px);
  animation: beaconFloat 10s ease-in-out infinite alternate;
  pointer-events: none;
}

.hero__inner::after,
.page-hero__inner::after {
  content: "";
  position: absolute;
  inset: auto auto 10% 4%;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  border: 1px dashed var(--hero-ring);
  opacity: 0.4;
  animation: spinHalo 24s linear infinite;
  pointer-events: none;
}

.hero::before {
  width: 360px;
  height: 360px;
  top: -80px;
  right: -40px;
  background: rgba(0, 245, 212, 0.16);
}

.hero::after {
  width: 320px;
  height: 320px;
  bottom: -100px;
  left: -60px;
  background: rgba(156, 140, 255, 0.16);
  animation-delay: -6s;
}

@keyframes heroGlow {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }
  to {
    transform: translate3d(20px, 24px, 0) scale(1.08);
  }
}

@keyframes beaconFloat {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }
  to {
    transform: translate3d(-28px, 18px, 0) scale(1.08);
  }
}

@keyframes spinHalo {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.hero__inner,
.page-hero__inner {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(280px, 0.75fr);
  gap: 2rem;
  align-items: center;
  min-height: calc(100vh - var(--nav-height));
  padding: 4rem 0 3rem;
  position: relative;
  z-index: 1;
}

.hero__content h1,
.page-hero__content h1 {
  font-size: clamp(3rem, 6vw, 5.6rem);
  letter-spacing: -0.06em;
}

.hero__content,
.page-hero__content {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.75s ease, transform 0.75s ease;
}

.hero__content h1,
.page-hero__content h1,
.section-header h2 {
  background: var(--title-gradient);
  background-size: 180% auto;
  -webkit-background-clip: text;
  background-clip: text;
  animation: titleSheen 7s linear infinite;
}

.hero-name-hover {
  display: inline-block;
  cursor: default;
  user-select: none;
  position: relative;
  isolation: isolate;
}

.hero-name-hover::before {
  content: "";
  position: absolute;
  inset: -8px;
  background: linear-gradient(
    110deg,
    transparent 0%,
    transparent 44%,
    var(--shine-overlay) 50%,
    transparent 56%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: nameShine 9s linear infinite;
  pointer-events: none;
  z-index: 2;
  mix-blend-mode: screen;
  filter: blur(14px);
  opacity: 0.55;
}

@keyframes nameShine {
  0% {
    background-position: 200% center;
  }
  100% {
    background-position: -200% center;
  }
}

.hero-name-hover::after {
  content: none;
}

.hero-name-hover span {
  display: inline-block;
  position: relative;
  isolation: isolate;
  transition:
    transform 0.18s ease,
    text-shadow 0.35s ease,
    filter 0.35s ease;
  text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
}

.hero-name-hover span::before,
.hero-name-hover span::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  mix-blend-mode: screen;
  transition: opacity 0.18s ease;
}

.hero-name-hover span::before {
  color: rgba(0, 245, 212, 0.9);
  text-shadow: -0.03em 0 0 rgba(0, 245, 212, 0.5);
}

.hero-name-hover span::after {
  color: rgba(255, 123, 141, 0.9);
  text-shadow: 0.03em 0 0 rgba(255, 123, 141, 0.45);
}

.hero-name-hover:hover span {
  filter: brightness(1.03);
}

.hero-name-hover:hover span:first-child {
  animation: nameGlitchPrimary 460ms steps(2, end) 1;
}

.hero-name-hover:hover span:last-child {
  animation: nameGlitchSecondary 520ms steps(2, end) 1;
}

.hero-name-hover:hover span::before,
.hero-name-hover:hover span::after {
  opacity: 0.72;
}

.hero-name-hover:hover span::before {
  animation: glitchLayerCyan 460ms steps(2, end) 1;
}

.hero-name-hover:hover span::after {
  animation: glitchLayerRose 520ms steps(2, end) 1;
}

.glitch-title {
  display: inline-block;
  cursor: default;
  position: relative;
  isolation: isolate;
}

.glitch-title span {
  display: inline-block;
  position: relative;
  isolation: isolate;
  transition:
    transform 0.18s ease,
    text-shadow 0.35s ease,
    filter 0.35s ease;
  text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
}

.glitch-title span::before,
.glitch-title span::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  mix-blend-mode: screen;
  transition: opacity 0.18s ease;
}

.glitch-title span::before {
  color: rgba(0, 245, 212, 0.9);
  text-shadow: -0.03em 0 0 rgba(0, 245, 212, 0.5);
}

.glitch-title span::after {
  color: rgba(255, 123, 141, 0.9);
  text-shadow: 0.03em 0 0 rgba(255, 123, 141, 0.45);
}

.glitch-title:hover span {
  filter: brightness(1.03);
  animation: nameGlitchPrimary 460ms steps(2, end) 1;
}

.glitch-title:hover span::before,
.glitch-title:hover span::after {
  opacity: 0.72;
}

.glitch-title:hover span::before {
  animation: glitchLayerCyan 460ms steps(2, end) 1;
}

.glitch-title:hover span::after {
  animation: glitchLayerRose 520ms steps(2, end) 1;
}

.about-title-special {
  display: inline-block;
  position: relative;
  isolation: isolate;
  transition:
    transform 0.28s ease,
    text-shadow 0.28s ease,
    letter-spacing 0.28s ease,
    filter 0.28s ease;
}

.about-title-special::before {
  content: "";
  position: absolute;
  inset: auto -0.15em -0.08em;
  height: 0.45em;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(0, 245, 212, 0.2), rgba(156, 140, 255, 0.28), rgba(255, 123, 141, 0.18));
  filter: blur(10px);
  opacity: 0;
  transform: scaleX(0.3);
  transform-origin: center;
  transition: opacity 0.28s ease, transform 0.4s ease;
  z-index: -1;
}

.about-title-special::after {
  content: "";
  position: absolute;
  left: -0.02em;
  right: -0.02em;
  bottom: -0.14em;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--cyan), var(--violet), var(--rose));
  transform: scaleX(0.22);
  transform-origin: left;
  transition: transform 0.38s ease;
}

.about-title-special:hover {
  transform: translateY(-2px) skewX(-4deg);
  letter-spacing: 0.015em;
  filter: brightness(1.04);
  text-shadow:
    -0.04em 0 0 rgba(0, 245, 212, 0.42),
    0.04em 0 0 rgba(156, 140, 255, 0.42),
    0 12px 24px rgba(6, 10, 18, 0.28);
}

.about-title-special:hover::before {
  opacity: 1;
  transform: scaleX(1);
}

.about-title-special:hover::after {
  transform: scaleX(1);
}

.about-hero-title {
  display: inline-block;
  position: relative;
  isolation: isolate;
  transition:
    transform 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    text-shadow 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    letter-spacing 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  text-shadow: 0 10px 24px rgba(6, 10, 18, 0.22);
}

.about-hero-title::before {
  content: "";
  position: absolute;
  inset: -0.12em -0.18em;
  border-radius: 0.28em;
  background:
    linear-gradient(
      115deg,
      transparent 0%,
      transparent 18%,
      rgba(0, 245, 212, 0.22) 28%,
      rgba(156, 140, 255, 0.26) 48%,
      rgba(255, 123, 141, 0.2) 68%,
      transparent 82%,
      transparent 100%
    );
  background-size: 220% 100%;
  opacity: 0;
  filter: blur(10px);
  transform: translateX(-16%) skewX(-14deg);
  transition:
    opacity 0.45s ease,
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    background-position 0.95s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: -2;
}

.about-hero-title::after {
  content: "";
  position: absolute;
  left: 0.02em;
  right: 0.02em;
  top: 54%;
  height: 0.42em;
  border-radius: 0.08em;
  background:
    linear-gradient(90deg, rgba(0, 245, 212, 0.22), rgba(156, 140, 255, 0.28), rgba(255, 123, 141, 0.2));
  opacity: 0;
  transform: scaleX(0.08) skewX(-24deg);
  transform-origin: left;
  filter: blur(5px);
  transition:
    opacity 0.4s ease,
    transform 0.75s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: -1;
}

.about-hero-title:hover {
  transform: translateY(-2px) scale(1.012);
  filter: brightness(1.05);
  letter-spacing: 0.012em;
  text-shadow:
    -0.016em 0 0 rgba(0, 245, 212, 0.32),
    0.016em 0 0 rgba(156, 140, 255, 0.32),
    0.045em 0 0 rgba(255, 123, 141, 0.18),
    0 14px 30px rgba(6, 10, 18, 0.34);
}

.about-hero-title:hover::before {
  opacity: 1;
  background-position: 100% 0;
  transform: translateX(4%) skewX(-14deg);
}

.about-hero-title:hover::after {
  opacity: 1;
  transform: scaleX(1) skewX(-24deg);
}

@keyframes nameGlitchPrimary {
  0% {
    transform: translate3d(0, 0, 0);
    text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
  }
  20% {
    transform: translate3d(-2px, 1px, 0);
  }
  40% {
    transform: translate3d(2px, -1px, 0);
    text-shadow:
      -0.05em 0 0 rgba(0, 245, 212, 0.5),
      0.05em 0 0 rgba(255, 123, 141, 0.35),
      0 10px 22px rgba(6, 10, 18, 0.24);
  }
  60% {
    transform: translate3d(-1px, 1px, 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
    text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
  }
}

@keyframes nameGlitchSecondary {
  0% {
    transform: translate3d(0, 0, 0);
    text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
  }
  18% {
    transform: translate3d(2px, 0, 0);
  }
  38% {
    transform: translate3d(-3px, 1px, 0);
    text-shadow:
      -0.04em 0 0 rgba(255, 123, 141, 0.42),
      0.04em 0 0 rgba(0, 245, 212, 0.42),
      0 10px 22px rgba(6, 10, 18, 0.24);
  }
  58% {
    transform: translate3d(1px, -1px, 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
    text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
  }
}

@keyframes glitchLayerCyan {
  0% {
    transform: translate3d(0, 0, 0);
    clip-path: inset(0 0 0 0);
  }
  25% {
    transform: translate3d(-4px, 0, 0);
    clip-path: inset(8% 0 55% 0);
  }
  50% {
    transform: translate3d(3px, -1px, 0);
    clip-path: inset(48% 0 18% 0);
  }
  75% {
    transform: translate3d(-2px, 1px, 0);
    clip-path: inset(72% 0 4% 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
    clip-path: inset(0 0 0 0);
  }
}

@keyframes glitchLayerRose {
  0% {
    transform: translate3d(0, 0, 0);
    clip-path: inset(0 0 0 0);
  }
  20% {
    transform: translate3d(4px, 0, 0);
    clip-path: inset(14% 0 52% 0);
  }
  45% {
    transform: translate3d(-3px, 1px, 0);
    clip-path: inset(56% 0 12% 0);
  }
  70% {
    transform: translate3d(2px, -1px, 0);
    clip-path: inset(34% 0 36% 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
    clip-path: inset(0 0 0 0);
  }
}

@keyframes titleSheen {
  from {
    background-position: 0% center;
  }
  to {
    background-position: 180% center;
  }
}

.hero-card {
  opacity: 0;
  transform: translateY(28px) scale(0.985);
  transition:
    opacity 0.8s ease,
    transform 0.8s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

body.is-ready .hero__content,
body.is-ready .page-hero__content,
body.is-ready .hero-card {
  opacity: 1;
  transform: translateY(0) scale(1);
}

body.is-ready .hero-card {
  transition-delay: 0.12s;
}

.hero__content p.lead,
.page-hero__content p.lead {
  max-width: 58ch;
  margin-top: 1.2rem;
  font-size: 1.08rem;
}

.hero__welcome {
  margin: 1.5rem 0 2rem;
  padding: 1rem 1.1rem;
  border: 1px solid rgba(0, 245, 212, 0.18);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
  max-width: 34rem;
  transition: transform 0.25s ease, border-color 0.25s ease, background 0.25s ease;
}

.hero__welcome:hover {
  transform: translateY(-2px);
  border-color: rgba(0, 245, 212, 0.3);
  background: rgba(255, 255, 255, 0.06);
}

.hero__actions,
.action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0.85rem 1.3rem;
  border-radius: 14px;
  font-weight: 700;
  border: 1px solid transparent;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
  cursor: pointer;
}

.btn:hover {
  transform: translateY(-2px) scale(1.02);
  animation: magneticPulse 0.6s ease;
}

@keyframes magneticPulse {
  0% {
    box-shadow: 0 0 0 0 rgba(0, 245, 212, 0.4);
  }
  50% {
    box-shadow: 0 0 0 10px rgba(0, 245, 212, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(0, 245, 212, 0);
  }
}

.btn::after {
  content: "";
  position: absolute;
  inset: -120% auto -120% -30%;
  width: 42%;
  transform: rotate(18deg) translateX(-180%);
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.28), transparent);
  transition: transform 0.6s ease;
}

.btn:hover::after {
  transform: rotate(18deg) translateX(520%);
}

.btn--primary {
  background: linear-gradient(135deg, #00f5d4, #00c4a7);
  color: #041017;
  box-shadow: 0 12px 30px rgba(0, 245, 212, 0.18);
}

.btn--secondary {
  background: var(--surface-overlay-strong);
  border-color: var(--border);
}

.btn--primary:hover {
  box-shadow: 0 18px 36px rgba(0, 245, 212, 0.24);
}

.btn--secondary:hover {
  border-color: rgba(156, 140, 255, 0.26);
  background: rgba(156, 140, 255, 0.08);
}

.hero-card,
.panel,
.card,
.project-card,
.timeline-card,
.competency-card,
.cv-panel,
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
  transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, transform 0.3s ease;
}

.hero-card {
  border-radius: 28px;
  padding: 1.5rem;
  position: relative;
  overflow: hidden;
  transform-style: preserve-3d;
}

.hero-card::before,
.panel::before,
.card::before,
.project-quicklink::before,
.project-card::before,
.competency-card::before,
.cv-panel::before,
.feature-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0, 245, 212, 0.1), transparent 35%, rgba(156, 140, 255, 0.08));
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.hero-card::after,
.panel::after,
.card::after,
.project-quicklink::after,
.project-card::after,
.competency-card::after,
.cv-panel::after,
.feature-card::after {
  content: none;
}

.hero-card:hover::before,
.panel:hover::before,
.card:hover::before,
.project-quicklink:hover::before,
.project-card:hover::before,
.competency-card:hover::before,
.cv-panel:hover::before,
.feature-card:hover::before {
  opacity: 1;
}

.hero-card__photo {
  aspect-ratio: 4 / 5;
  overflow: hidden;
  border-radius: 22px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transform: translateZ(0);
}

.hero-card__photo--interactive {
  position: relative;
  cursor: pointer;
  isolation: isolate;
}

.hero-card__photo--interactive:focus-visible {
  outline: 2px solid rgba(0, 245, 212, 0.8);
  outline-offset: 4px;
}

.hero-card__photo-burst {
  position: absolute;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border-radius: 50%;
  pointer-events: none;
  z-index: 3;
  animation: fireworkBurst 850ms ease-out forwards;
}

.hero-card__photo-spark {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 4px;
  height: 24px;
  margin-left: -2px;
  margin-top: -22px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), currentColor 70%, rgba(255, 255, 255, 0));
  transform-origin: 50% 100%;
  animation: fireworkSpark 850ms ease-out forwards;
}

@keyframes fireworkBurst {
  0% {
    transform: scale(0.2);
    opacity: 0;
  }
  18% {
    opacity: 1;
  }
  100% {
    transform: scale(1.05);
    opacity: 0;
  }
}

@keyframes fireworkSpark {
  0% {
    transform: rotate(var(--angle)) translateY(0) scaleY(0.4);
    opacity: 1;
  }
  100% {
    transform: rotate(var(--angle)) translateY(calc(var(--distance) * -1)) scaleY(1.05);
    opacity: 0;
  }
}

.hero-card__photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.7s ease, filter 0.35s ease;
}

.hero-card:hover .hero-card__photo img {
  transform: scale(1.045);
  filter: saturate(1.06);
}

.hero-card__meta {
  display: grid;
  gap: 0.8rem;
  margin-top: 1rem;
}

.meta-pill {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.9rem 1rem;
  border-radius: 16px;
  background: var(--surface-overlay);
  transition: transform 0.22s ease, background 0.22s ease;
}

.hero-card:hover .meta-pill {
  transform: translateX(4px);
  background: var(--surface-overlay-strong);
}

.meta-pill span:first-child {
  color: var(--text-muted);
  font-size: 0.84rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.meta-pill strong {
  display: block;
  font-size: 0.95rem;
}

.grid-two,
.grid-three,
.skills-grid,
.projects-overview,
.competency-grid,
.cv-grid,
.gallery-grid,
.details-grid,
.hobby-grid,
.contact-grid {
  display: grid;
  gap: 1.25rem;
}

.grid-two,
.details-grid,
.cv-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid-three,
.skills-grid,
.projects-overview,
.competency-grid,
.gallery-grid,
.hobby-grid,
.contact-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.panel,
.card,
.feature-card,
.cv-panel {
  border-radius: var(--radius);
  padding: 1.5rem;
  position: relative;
  overflow: hidden;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease, background 0.24s ease;
}

.panel:hover,
.card:hover,
.feature-card:hover,
.cv-panel:hover,
.competency-card:hover,
.project-quicklink:hover {
  transform: translateY(-8px) rotateX(0.8deg) rotateY(-0.8deg);
  border-color: rgba(0, 245, 212, 0.22);
  box-shadow: 0 28px 52px rgba(0, 0, 0, 0.32);
}

.card h3,
.feature-card h3,
.cv-panel h3,
.timeline-card h3,
.project-card h3 {
  font-size: 1.25rem;
  letter-spacing: -0.03em;
  margin-bottom: 0.75rem;
}

.feature-card--identity {
  isolation: isolate;
  background:
    radial-gradient(circle at 85% 15%, rgba(0, 245, 212, 0.1), transparent 28%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.02));
}

.feature-card--identity::after {
  content: "";
  position: absolute;
  inset: -35%;
  background:
    conic-gradient(
      from 0deg,
      transparent 0deg,
      rgba(0, 245, 212, 0.3) 60deg,
      rgba(156, 140, 255, 0.38) 140deg,
      rgba(255, 123, 141, 0.28) 220deg,
      transparent 300deg
    );
  opacity: 0;
  filter: blur(28px);
  transform: scale(0.75) rotate(0deg);
  transition: opacity 0.35s ease, transform 0.7s ease;
  pointer-events: none;
  z-index: 0;
}

.feature-card--identity > * {
  position: relative;
  z-index: 1;
}

.feature-card--identity h3 {
  transition: transform 0.35s ease, letter-spacing 0.35s ease, text-shadow 0.35s ease;
}

.feature-card--identity p {
  transition: transform 0.35s ease, color 0.35s ease;
}

.feature-card--identity:hover {
  transform: translateY(-10px) rotateX(2deg) rotateY(-2deg) scale(1.015);
  border-color: rgba(156, 140, 255, 0.3);
  box-shadow:
    0 30px 56px rgba(0, 0, 0, 0.34),
    0 0 0 1px rgba(156, 140, 255, 0.12);
}

.feature-card--identity:hover::after {
  opacity: 1;
  transform: scale(1) rotate(120deg);
}

.feature-card--identity:hover h3 {
  transform: translateX(6px);
  letter-spacing: 0.01em;
  text-shadow:
    -0.04em 0 0 rgba(0, 245, 212, 0.45),
    0.04em 0 0 rgba(156, 140, 255, 0.4),
    0 10px 24px rgba(6, 10, 18, 0.3);
}

.feature-card--identity:hover p {
  transform: translateX(3px);
  color: var(--text);
}

.list {
  display: grid;
  gap: 0.7rem;
}

.list li {
  position: relative;
  padding-left: 1rem;
  color: var(--text-soft);
}

.list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.7rem;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--cyan);
}

.project-section-header {
  margin-top: 2.5rem;
}

#project-list .skills-grid {
  /* enforce exact 50/50 columns for hard / soft skills */
  grid-template-columns: 1fr 1fr;
}

/* Make all direct children of two-column grids align to start to avoid vertical stretching */
.grid-two > * {
  align-self: start;
}

#semester-2 .grid-two > .card {
  align-self: start;
}

.project-image {
  width: 100%;
  margin-bottom: 1rem;
  border-radius: 14px;
  border: 1px solid var(--border);
}

.skill-group {
  border-radius: var(--radius);
  padding: 1.5rem;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
  border: 1px solid var(--border);
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.skill-group:hover {
  transform: translateY(-8px) rotateX(0.7deg);
  border-color: rgba(156, 140, 255, 0.24);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.28);
}

.skill-group ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin-top: 1rem;
}

.skill-group li,
.tag {
  display: inline-flex;
  align-items: center;
  padding: 0.5rem 0.8rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--text-soft);
  font-size: 0.92rem;
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, color 0.18s ease;
}

.skill-group li:hover,
.tag:hover {
  transform: translateY(-2px);
  border-color: rgba(0, 245, 212, 0.24);
  background: rgba(0, 245, 212, 0.08);
  color: var(--text);
}

.project-quicklink {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1.5rem;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
  position: relative;
  overflow: hidden;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.project-quicklink--featured {
  background:
    radial-gradient(circle at top right, rgba(255, 209, 102, 0.14), transparent 34%),
    linear-gradient(135deg, rgba(255, 123, 141, 0.1), rgba(156, 140, 255, 0.12) 46%, rgba(0, 245, 212, 0.08));
  border-color: rgba(255, 209, 102, 0.18);
}

.project-quicklink__eyebrow {
  display: inline-flex;
  margin-bottom: 0.55rem;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold);
}

.project-quicklink__meta {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.project-quicklink--featured .project-summary {
  max-width: 42ch;
}

.project-quicklink:hover {
  transform: translateY(-8px) scale(1.01);
  border-color: rgba(156, 140, 255, 0.24);
  box-shadow: 0 26px 52px rgba(0, 0, 0, 0.3);
}

.project-quicklink__top {
  position: relative;
  z-index: 1;
}

.project-summary,
.project-quicklink .link-arrow {
  position: relative;
  z-index: 1;
}

.project-quicklink__top {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
  flex-wrap: wrap;
}

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  width: fit-content;
  min-height: 2rem;
  padding: 0.5rem 0.85rem;
  border-radius: 999px;
  font-size: 0.76rem;
  line-height: 1.1;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
  white-space: nowrap;
  flex-shrink: 0;
  position: relative;
  transition: transform 0.2s ease;
}

.badge:hover {
  animation: glitchBadge 0.5s ease;
}

@keyframes glitchBadge {
  0%, 100% {
    transform: translate(0);
  }
  20% {
    transform: translate(-2px, 2px);
  }
  40% {
    transform: translate(2px, -2px);
  }
  60% {
    transform: translate(-1px, -1px);
  }
  80% {
    transform: translate(1px, 1px);
  }
}

.badge--cyan {
  color: var(--cyan);
  background: rgba(0, 245, 212, 0.1);
}

.badge--violet {
  color: var(--violet);
  background: rgba(156, 140, 255, 0.1);
}

.badge--rose {
  color: var(--rose);
  background: rgba(255, 123, 141, 0.1);
}

.badge--green {
  color: var(--green);
  background: rgba(68, 215, 168, 0.12);
}

.badge--gold {
  color: var(--gold);
  background: rgba(255, 209, 102, 0.1);
}

/* Unique award badge styling */
.award-badge {
  display: inline-block;
  margin-top: 0.7rem;
  position: relative;
}

.award-badge__inner {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.15rem;
  padding: 0.5rem 0.8rem 0.5rem 1.1rem;
  background: linear-gradient(135deg, rgba(255, 209, 102, 0.08) 0%, rgba(255, 209, 102, 0.04) 100%);
  border: 1px solid rgba(255, 209, 102, 0.18);
  border-left: 3px solid var(--gold);
  border-radius: 4px;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
  cursor: default;
}

.award-badge__inner::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.15) 50%, transparent 100%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}

.award-badge__label {
  display: block;
  font-size: 0.55rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 500;
  opacity: 0.68;
  line-height: 1;
}

.award-badge__label--strong {
  font-size: 0.64rem;
  font-weight: 700;
  opacity: 0.88;
  letter-spacing: 0.14em;
}

.award-badge:hover .award-badge__inner {
  background: linear-gradient(135deg, rgba(255, 209, 102, 0.12) 0%, rgba(255, 209, 102, 0.06) 100%);
  border-color: rgba(255, 209, 102, 0.28);
  box-shadow: 0 4px 12px rgba(255, 209, 102, 0.12);
}

.award-badge:hover .award-badge__inner::before {
  animation: glossSlide 0.6s ease;
}

@keyframes glossSlide {
  0% {
    opacity: 0;
    transform: translateX(-100%);
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateX(100%);
  }
}

.project-summary {
  color: var(--text-soft);
}

.link-arrow {
  color: var(--cyan);
  font-weight: 700;
  transition: letter-spacing 0.18s ease, color 0.18s ease;
}

.project-quicklink:hover .link-arrow,
.footer__col ul a:hover,
.footer__contact-value:hover {
  letter-spacing: 0.02em;
}

.timeline {
  display: grid;
  gap: 1rem;
}

.timeline-card {
  border-radius: var(--radius);
  padding: 1.5rem;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.timeline-card:hover {
  transform: translateX(12px) scale(1.01);
  border-color: rgba(0, 245, 212, 0.2);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.28);
}

.timeline-card__year {
  display: inline-block;
  margin-bottom: 0.8rem;
  color: var(--cyan);
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
}

.project-card {
  border-radius: 28px;
  padding: 1.7rem;
  margin-bottom: 1.5rem;
  position: relative;
  overflow: hidden;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.project-card:hover {
  transform: translateY(-10px) scale(1.004);
  border-color: rgba(0, 245, 212, 0.22);
  box-shadow: 0 30px 56px rgba(0, 0, 0, 0.34);
}

.chez-showcase {
  position: relative;
  overflow: hidden;
  margin-bottom: 1.5rem;
  padding: clamp(1.25rem, 3vw, 2rem);
  border: 1px solid rgba(255, 209, 102, 0.18);
  border-radius: 28px;
  background:
    linear-gradient(135deg, rgba(255, 209, 102, 0.11), transparent 28%),
    radial-gradient(circle at 88% 12%, rgba(0, 245, 212, 0.14), transparent 30%),
    radial-gradient(circle at 14% 86%, rgba(156, 140, 255, 0.16), transparent 34%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.018));
  box-shadow: 0 28px 64px rgba(0, 0, 0, 0.28);
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.chez-showcase::before {
  content: "";
  position: absolute;
  inset: -1px;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.13) 50%, transparent 100%),
    linear-gradient(rgba(255, 255, 255, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.035) 1px, transparent 1px);
  background-size: 220% 100%, 42px 42px, 42px 42px;
  opacity: 0.42;
  transform: translateX(-18%);
  transition: transform 0.8s ease, opacity 0.3s ease;
}

.chez-showcase:hover {
  transform: translateY(-10px) scale(1.002);
  border-color: rgba(255, 209, 102, 0.3);
  box-shadow: 0 34px 70px rgba(0, 0, 0, 0.35);
}

.chez-showcase:hover::before {
  opacity: 0.7;
  transform: translateX(0);
}

.chez-showcase__intro,
.chez-showcase__stage,
.chez-showcase__workflow,
.chez-showcase__reflection {
  position: relative;
  z-index: 1;
}

.chez-showcase__intro {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(280px, 0.75fr);
  gap: 1.5rem;
  align-items: end;
  margin-bottom: 1.6rem;
}

.chez-showcase__intro h2 {
  max-width: 12ch;
  font-size: clamp(2rem, 4vw, 4rem);
  letter-spacing: -0.055em;
}

.chez-showcase__intro p {
  margin: 0;
  font-size: 1.02rem;
}

.chez-showcase__stage {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(300px, 0.7fr);
  gap: 1.2rem;
  align-items: stretch;
}

.chez-showcase__visual {
  position: relative;
  min-height: 480px;
  overflow: hidden;
  border-radius: 26px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background:
    linear-gradient(135deg, rgba(7, 11, 20, 0.16), rgba(7, 11, 20, 0.78)),
    rgba(8, 12, 22, 0.86);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 24px 48px rgba(0, 0, 0, 0.22);
}

.chez-showcase__visual img {
  width: 100%;
  height: 100%;
  min-height: 480px;
  object-fit: contain;
  object-position: center top;
  display: block;
  filter: saturate(1.04) contrast(1.02);
  transition: transform 0.7s ease, filter 0.35s ease;
}

.chez-showcase:hover .chez-showcase__visual img {
  transform: scale(1.025);
  filter: saturate(1.12) contrast(1.04);
}

.chez-showcase__pin {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 0.72rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(7, 11, 20, 0.78);
  color: var(--text);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  backdrop-filter: blur(14px);
  box-shadow: 0 16px 34px rgba(0, 0, 0, 0.28);
}

.chez-showcase__pin::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--gold);
  box-shadow: 0 0 0 5px rgba(255, 209, 102, 0.14);
}

.chez-showcase__pin--rooms {
  left: 1.2rem;
  top: 1.2rem;
}

.chez-showcase__pin--booking {
  right: 1.2rem;
  top: 48%;
}

.chez-showcase__pin--client {
  left: 1.2rem;
  bottom: 1.2rem;
}

.chez-showcase__brief {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.95rem;
  padding: 1.35rem;
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.045);
}

.chez-showcase__brief-top,
.chez-showcase__workflow {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.chez-showcase__brief h3 {
  font-size: clamp(1.4rem, 2.4vw, 2.1rem);
  letter-spacing: -0.04em;
}

.chez-showcase__brief p:last-child,
.chez-showcase__workflow p,
.chez-showcase__reflection p {
  margin-bottom: 0;
}

.chez-showcase__workflow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 1rem;
  counter-reset: chez-step;
}

.chez-showcase__workflow section {
  min-height: 185px;
  padding: 1rem;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(255, 255, 255, 0.04);
  transition: transform 0.22s ease, border-color 0.22s ease, background 0.22s ease;
}

.chez-showcase__workflow section:hover {
  transform: translateY(-6px);
  border-color: rgba(0, 245, 212, 0.22);
  background: rgba(0, 245, 212, 0.06);
}

.chez-showcase__workflow span {
  display: inline-flex;
  margin-bottom: 0.8rem;
  color: var(--gold);
  font-weight: 800;
  letter-spacing: 0.12em;
}

.chez-showcase__workflow h4,
.chez-showcase__reflection h4 {
  margin-bottom: 0.55rem;
}

.chez-showcase__reflection {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.chez-showcase__reflection > div {
  padding: 1.2rem;
  border-left: 3px solid var(--gold);
  border-radius: 0 18px 18px 0;
  background: rgba(255, 209, 102, 0.065);
}

.project-card__header {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.project-card__hero {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(320px, 0.95fr);
  gap: 1.4rem;
  align-items: center;
  width: 100%;
}

.project-card__hero-copy {
  display: grid;
  gap: 0.9rem;
}

.project-card__eyebrow {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 0.55rem;
  padding: 0.35rem 0.8rem;
  border-radius: 999px;
  background: rgba(255, 209, 102, 0.12);
  border: 1px solid rgba(255, 209, 102, 0.16);
  color: var(--gold);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.project-card__hero-side {
  display: grid;
  gap: 1rem;
}

.project-card__lead {
  margin: 0;
  max-width: 52ch;
  font-size: 1.05rem;
  color: var(--text-soft);
}

.project-card__featured-points {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem;
  margin-top: 0.35rem;
}

.project-card__point {
  padding: 1rem;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(10px);
}

.project-card__point span {
  display: block;
  margin-bottom: 0.35rem;
  color: var(--gold);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.project-card__point strong {
  display: block;
  color: var(--text);
  line-height: 1.35;
}

.project-card__hero-visual {
  margin: 0;
  min-height: 420px;
  border-radius: 28px;
  overflow: hidden;
  border: 1px solid rgba(255, 209, 102, 0.18);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.01)),
    linear-gradient(145deg, rgba(12, 18, 32, 0.96), rgba(24, 16, 38, 0.88));
  box-shadow: 0 28px 60px rgba(0, 0, 0, 0.32);
  transform: rotate(1.2deg);
}

.project-card__hero-visual img {
  width: 100%;
  height: 100%;
  min-height: 420px;
  object-fit: contain;
  object-position: center top;
  display: block;
  background: rgba(8, 12, 22, 0.88);
}

.project-card--featured {
  background:
    radial-gradient(circle at top right, rgba(255, 209, 102, 0.14), transparent 24%),
    radial-gradient(circle at bottom left, rgba(0, 245, 212, 0.08), transparent 28%),
    linear-gradient(135deg, rgba(255, 123, 141, 0.06), rgba(255, 255, 255, 0.03) 36%, rgba(0, 245, 212, 0.06));
  border-color: rgba(255, 209, 102, 0.18);
}

.project-card--featured::before {
  opacity: 1;
  background:
    linear-gradient(135deg, rgba(255, 209, 102, 0.08), transparent 22%, rgba(0, 245, 212, 0.06)),
    linear-gradient(180deg, transparent, rgba(255, 255, 255, 0.025));
}

.project-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 0.9rem;
}

.project-card__content {
  display: grid;
  gap: 1rem;
}

.project-card section {
  padding: 1rem 0;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.project-card section:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.project-card h4 {
  margin-bottom: 0.55rem;
  font-size: 1rem;
  color: var(--text);
}

.gallery-grid figure {
  margin: 0;
  overflow: hidden;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.gallery-grid img {
  width: 100%;
  height: 210px;
  object-fit: cover;
  transition: transform 0.7s ease, filter 0.35s ease;
}

.gallery-grid figcaption {
  padding: 0.8rem 1rem 1rem;
  color: var(--text-soft);
  font-size: 0.92rem;
}

.gallery-grid figure:hover {
  transform: translateY(-8px) rotate(-0.4deg);
  border-color: rgba(156, 140, 255, 0.24);
  box-shadow: 0 24px 46px rgba(0, 0, 0, 0.3);
}

.gallery-grid figure:hover img {
  transform: scale(1.04);
  filter: saturate(1.08);
}

.gallery-grid--featured {
  grid-template-columns: minmax(0, 1fr);
}

.gallery-grid--featured figure {
  border-radius: 24px;
}

.gallery-grid--featured img {
  height: 520px;
  object-position: center top;
}

.competency-card {
  border-radius: 22px;
  padding: 1.35rem;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
  position: relative;
  overflow: hidden;
}

.competency-card h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.cv-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
  gap: 1.5rem;
  align-items: start;
}

.cv-panel--accent {
  background: linear-gradient(135deg, rgba(0, 245, 212, 0.12), rgba(156, 140, 255, 0.12));
}

.cv-heading {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: start;
  margin-bottom: 1rem;
}

.cv-block + .cv-block {
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.cv-item + .cv-item {
  margin-top: 1rem;
}

.cv-item__meta {
  color: var(--cyan);
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 0.35rem;
}

.cv-download {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin-top: 1.4rem;
}

.cv-preview {
  display: grid;
  grid-template-columns: minmax(260px, 0.8fr) minmax(0, 1.6fr);
  gap: 1.5rem;
  align-items: start;
}

.cv-preview__info {
  display: grid;
  gap: 1rem;
}

.cv-preview__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin-top: 0.25rem;
}

.cv-preview__viewer-panel {
  display: grid;
  gap: 1rem;
}

.cv-preview__viewer-shell {
  min-height: 780px;
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02)),
    rgba(3, 8, 16, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.cv-preview__viewer {
  width: 100%;
  height: 780px;
  border: 0;
  display: block;
  background: #ffffff;
}

.cv-preview__fallback {
  margin: 0;
  font-size: 0.94rem;
  color: var(--text-muted);
}

.cv-preview__fallback a {
  color: var(--cyan);
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1.8rem;
}

.stat-card {
  padding: 1.2rem;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.07);
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.stat-card:hover {
  transform: translateY(-8px) scale(1.02);
  border-color: rgba(0, 245, 212, 0.2);
  box-shadow: 0 22px 40px rgba(0, 0, 0, 0.24);
}

.stat-card strong,
.meta-pill strong {
  background: var(--title-gradient);
  background-size: 180% auto;
  -webkit-background-clip: text;
  background-clip: text;
  animation: titleSheen 8s linear infinite;
}

.hero__welcome,
.meta-pill,
.stat-card,
.skill-group li,
.tag,
.footer__badge,
.badge {
  backdrop-filter: blur(10px);
}

.stat-card strong {
  display: block;
  font-size: 1.85rem;
  letter-spacing: -0.05em;
  margin-bottom: 0.35rem;
}

.site-footer {
  padding: 2rem 0 2.4rem;
  border-top: 1px solid var(--border);
  background: rgba(7, 11, 20, 0.7);
}

.site-footer__inner {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
}

.site-footer__links {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  color: var(--text-soft);
}

.site-footer p {
  margin: 0;
  color: var(--text-muted);
}

.footer {
  position: relative;
  overflow: hidden;
  background: var(--footer-bg);
  border-top: 1px solid var(--border);
  padding-top: 5rem;
}

.footer::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--footer-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--footer-grid) 1px, transparent 1px);
  background-size: 40px 40px;
  mask-image: radial-gradient(circle at center, black 20%, transparent 90%);
  opacity: 0.4;
  pointer-events: none;
}

.footer::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-gradient);
  opacity: 0.55;
}

.footer__glow-1,
.footer__glow-2 {
  display: none;
}

.footer__main {
  display: grid;
  grid-template-columns: 1.7fr 1fr 1fr 1.1fr;
  gap: 3rem;
  padding-bottom: 3.5rem;
  border-bottom: 1px solid var(--border);
  position: relative;
  z-index: 1;
}

.footer__brand-logo {
  display: block;
  font-size: 2.2rem;
  font-weight: 800;
  letter-spacing: -0.05em;
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 1rem;
}

.footer__brand-tagline {
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.footer__brand-desc {
  max-width: 320px;
  margin-bottom: 1.4rem;
}

.footer__socials {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.footer__social-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  width: fit-content;
  padding: 0.65rem 1rem;
  border-radius: var(--radius-small);
  background: var(--bg-card-strong);
  border: 1px solid var(--border);
  color: var(--text-soft);
  transition: border-color 0.25s ease, background 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease;
}

.footer__social-btn:hover {
  transform: translateX(4px);
  box-shadow: 0 16px 28px rgba(0, 0, 0, 0.22);
}

.footer__social-btn svg {
  transition: transform 0.22s ease;
}

.footer__social-btn:hover svg {
  transform: scale(1.14) rotate(-6deg);
}

.footer__social-btn--linkedin:hover {
  border-color: rgba(156, 140, 255, 0.35);
  background: rgba(156, 140, 255, 0.08);
  color: var(--violet);
}

.footer__social-btn--email:hover {
  border-color: rgba(255, 123, 141, 0.35);
  background: rgba(255, 123, 141, 0.08);
  color: var(--rose);
}

.footer__social-btn--labeled:not(.footer__social-btn--linkedin):not(.footer__social-btn--email):hover {
  border-color: rgba(0, 245, 212, 0.35);
  background: rgba(0, 245, 212, 0.08);
  color: var(--cyan);
}

.footer__col-title {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 1.4rem;
}

.footer__col ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer__col ul a {
  color: var(--text-soft);
  transition: color 0.2s ease, padding-left 0.2s ease;
}

.footer__col ul a:hover {
  color: var(--cyan);
  padding-left: 5px;
}

.footer__available {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  background: rgba(68, 215, 168, 0.08);
  border: 1px solid rgba(68, 215, 168, 0.25);
  border-radius: 14px;
  padding: 0.8rem 1rem;
  margin-bottom: 1.2rem;
}

.footer__available-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 0 rgba(68, 215, 168, 0.5);
  animation: footerPulse 2.2s ease-in-out infinite;
}

@keyframes footerPulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(68, 215, 168, 0.5);
  }
  50% {
    box-shadow: 0 0 0 9px rgba(68, 215, 168, 0);
  }
}

.footer__available-text {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--green);
}

.footer__contact-item {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  padding: 0.7rem 0;
  border-bottom: 1px solid var(--border);
}

.footer__contact-item:last-child {
  border-bottom: 0;
}

.footer__contact-label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.footer__contact-value {
  color: var(--text-soft);
}

.footer__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  padding: 2rem 0;
  position: relative;
  z-index: 1;
}

.footer__copy {
  font-size: 0.92rem;
  color: var(--text-muted);
}

.footer__badges {
  display: flex;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.footer__badge {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.74rem;
  font-weight: 600;
  line-height: 1.1;
  padding: 0.45rem 0.8rem;
  border-radius: 999px;
  overflow: hidden;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.footer__badge:hover {
  transform: none;
}

.badge {
  position: relative;
  overflow: hidden;
}

.badge::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.16), transparent);
  transform: translateX(-120%);
  transition: transform 0.55s ease;
}

.badge:hover::after {
  transform: translateX(120%);
}

.reveal {
  opacity: 0;
  transform: translateY(22px) scale(0.98);
  transition: opacity 0.6s ease, transform 0.6s ease, filter 0.6s ease;
  filter: blur(8px);
}

.reveal.is-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
  filter: blur(0);
}

.panel,
.card,
.project-quicklink,
.project-card,
.competency-card,
.cv-panel,
.feature-card,
.skill-group,
.timeline-card,
.stat-card,
.hero-card,
.gallery-grid figure {
  will-change: transform;
}

.footer__badge--cyan {
  color: var(--cyan);
  background: rgba(0, 245, 212, 0.1);
  border: 1px solid rgba(0, 245, 212, 0.22);
}

.footer__badge--violet {
  color: var(--violet);
  background: rgba(156, 140, 255, 0.1);
  border: 1px solid rgba(156, 140, 255, 0.22);
}

.footer__badge--rose {
  color: var(--rose);
  background: rgba(255, 123, 141, 0.1);
  border: 1px solid rgba(255, 123, 141, 0.22);
}

.muted {
  color: var(--text-muted);
}

/* Floating particles effect */
.hero::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  background-image: 
    radial-gradient(circle at 20% 30%, rgba(0, 245, 212, 0.15) 1px, transparent 1px),
    radial-gradient(circle at 60% 70%, rgba(156, 140, 255, 0.15) 1px, transparent 1px),
    radial-gradient(circle at 80% 20%, rgba(255, 123, 141, 0.15) 1px, transparent 1px);
  background-size: 50px 50px, 80px 80px, 100px 100px;
  animation: particleFloat 20s linear infinite;
  pointer-events: none;
  opacity: 0.4;
  z-index: 0;
}

@keyframes particleFloat {
  0% {
    transform: translateY(0);
  }
  100% {
    transform: translateY(-50px);
  }
}

/* Text glow effect on hover */
.hero__content h1:hover,
.page-hero__content h1:hover {
  text-shadow: 
    0 0 20px rgba(0, 245, 212, 0.6),
    0 0 40px rgba(0, 245, 212, 0.4),
    0 0 60px rgba(0, 245, 212, 0.2);
  transition: text-shadow 0.3s ease;
}

/* Ripple effect for stats cards */
.stat-card {
  position: relative;
  overflow: hidden;
}

.stat-card::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0, 245, 212, 0.3), transparent);
  transform: translate(-50%, -50%);
  transition: width 0.6s ease, height 0.6s ease;
}

.stat-card:hover::before {
  width: 300px;
  height: 300px;
}

/* Smooth color transition for links */
.link-arrow::after {
  content: "→";
  display: inline-block;
  margin-left: 0.5rem;
  transition: transform 0.3s ease, margin-left 0.3s ease;
}

.link-arrow:hover::after {
  transform: translateX(5px);
  margin-left: 0.8rem;
}

/* Skill group animation */
.skill-group li {
  transition: transform 0.2s ease, color 0.2s ease;
}

.skill-group:hover li {
  opacity: 0.5;
}

.skill-group li:hover {
  transform: translateX(10px) scale(1.05);
  opacity: 1 !important;
  color: var(--cyan);
}

/* Hero card photo interaction removed to avoid scroll/overlay problems */
.hero-card__photo {
  overflow: hidden;
  border-radius: 18px;
}

.hero-card__photo img {
  transition: filter 0.2s ease;
}

/* No hover scale/zoom - keeps layout stable */
.hero-card:hover .hero-card__photo img {
  transform: none;
  filter: none;
}

/* Eyebrow pulse animation */
.eyebrow::before {
  animation: eyebrowPulse 2s ease-in-out infinite;
}

@keyframes eyebrowPulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* Footer social button icons rotate */
.footer__social-btn:hover svg {
  animation: iconSpin 0.6s ease;
}

@keyframes iconSpin {
  0% {
    transform: scale(1) rotate(0deg);
  }
  50% {
    transform: scale(1.14) rotate(180deg);
  }
  100% {
    transform: scale(1.14) rotate(360deg);
  }
}

@media (max-width: 980px) {
  .hero__inner,
  .page-hero__inner,
  .cv-layout,
  .cv-preview,
  .grid-two,
  .details-grid,
  .cv-grid {
    grid-template-columns: 1fr;
  }

  .grid-three,
  .skills-grid,
  .projects-overview,
  .competency-grid,
  .gallery-grid,
  .hobby-grid,
  .contact-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .hero-card {
    max-width: 460px;
  }

  .footer__main {
    grid-template-columns: 1fr 1fr;
    gap: 2.5rem;
  }

  .project-card__hero {
    grid-template-columns: 1fr;
  }

  .chez-showcase__intro,
  .chez-showcase__stage,
  .chez-showcase__reflection {
    grid-template-columns: 1fr;
  }

  .chez-showcase__workflow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .project-card__featured-points {
    grid-template-columns: 1fr;
  }

  .project-card__hero-visual,
  .project-card__hero-visual img {
    min-height: 300px;
    transform: none;
  }

  .gallery-grid--featured img {
    height: 360px;
  }
}

@media (max-width: 760px) {
  :root {
    --nav-height: 82px;
  }

  .container {
    width: min(var(--max-width), calc(100% - 1.25rem));
  }

  .nav {
    gap: 0.75rem;
  }

  .nav > nav {
    margin-left: 0;
  }

  .brand {
    min-width: 0;
    gap: 0.7rem;
  }

  .brand__mark {
    min-width: 48px;
    height: 38px;
    padding: 0 0.55rem;
    font-size: 0.9rem;
  }

  .brand__name {
    font-size: 0.9rem;
  }

  .brand__role {
    font-size: 0.68rem;
  }

  .nav__toggle {
    display: block;
    flex-shrink: 0;
  }

  .theme-toggle {
    padding-inline: 0.55rem;
  }

  .theme-toggle__text {
    display: none;
  }

  .nav__links {
    position: fixed;
    inset: var(--nav-height) 1rem auto 1rem;
    display: none;
    flex-direction: column;
    align-items: stretch;
    gap: 0.2rem;
    padding: 0.75rem;
    border-radius: 20px;
    border: 1px solid var(--border);
    background: var(--mobile-menu-bg);
    box-shadow: var(--shadow);
  }

  .nav__links.is-open {
    display: flex;
  }

  .nav__link {
    padding: 0.8rem 0.9rem;
    border-radius: 12px;
  }

  .nav__link::after {
    display: none;
  }

  .nav__link:hover,
  .nav__link[aria-current="page"] {
    background: var(--nav-link-hover-bg);
  }

  .section {
    padding: 4rem 0;
  }

  .hero {
    padding-top: 0.4rem;
  }

  .hero__inner,
  .page-hero__inner {
    gap: 1.4rem;
    padding-block: 2.6rem 2.2rem;
  }

  .hero__content h1,
  .page-hero__content h1 {
    font-size: clamp(2.5rem, 10vw, 4rem);
  }

  .hero__content,
  .page-hero__content {
    gap: 1rem;
  }

  .hero__actions,
  .cv-download,
  .cv-preview__actions {
    flex-direction: column;
    align-items: stretch;
  }

  .hero__actions .btn,
  .cv-download .btn,
  .cv-download a,
  .cv-preview__actions .btn,
  .cv-preview__actions a {
    width: 100%;
    justify-content: center;
  }

  .cv-preview__viewer-shell,
  .cv-preview__viewer {
    min-height: 620px;
    height: 620px;
  }

  .hero-card,
  .project-card,
  .feature-card,
  .cv-panel,
  .timeline-card,
  .project-quicklink,
  .skill-group,
  .competency-card {
    padding: 1.2rem;
  }

  .hero-card {
    max-width: none;
  }

  .hero-card__meta {
    grid-template-columns: 1fr;
  }

  .meta-pill {
    min-width: 0;
  }

  .project-card {
    border-radius: 22px;
  }

  .chez-showcase {
    border-radius: 22px;
  }

  .chez-showcase__visual,
  .chez-showcase__visual img {
    min-height: 330px;
  }

  .chez-showcase__pin {
    position: static;
    margin: 0.6rem 0 0 0.6rem;
  }

  .chez-showcase__workflow {
    grid-template-columns: 1fr;
  }

  .chez-showcase__workflow section {
    min-height: 0;
  }

  .stats-row,
  .grid-three,
  .skills-grid,
  .projects-overview,
  .competency-grid,
  .gallery-grid,
  .hobby-grid,
  .contact-grid {
    grid-template-columns: 1fr;
  }

  .project-card__header,
  .cv-heading,
  .site-footer__inner {
    flex-direction: column;
    align-items: start;
  }

  .project-card__meta,
  .cv-item__meta {
    gap: 0.45rem;
  }

  .gallery-grid img {
    height: 190px;
  }

  .gallery-grid--featured img {
    height: 260px;
  }

  .footer__main,
  .footer__bottom,
  .site-footer__inner {
    gap: 1rem;
  }

  .footer__main {
    grid-template-columns: 1fr;
  }

  .footer__bottom {
    flex-direction: column;
    align-items: start;
  }
}

@media (max-width: 480px) {
  .container {
    width: min(var(--max-width), calc(100% - 1rem));
  }

  .section {
    padding: 3.25rem 0;
  }

  .nav {
    gap: 0.5rem;
  }

  .brand__text {
    min-width: 0;
  }

  .brand__name,
  .brand__role {
    white-space: normal;
  }

  .nav__links {
    inset-inline: 0.5rem;
  }

  .hero__inner,
  .page-hero__inner {
    padding-block: 2.2rem 1.9rem;
  }

  .hero__content h1,
  .page-hero__content h1 {
    font-size: clamp(2.15rem, 12vw, 3rem);
  }

  .section-header h2 {
    font-size: clamp(1.8rem, 8vw, 2.3rem);
  }

  .hero-card,
  .project-card,
  .feature-card,
  .cv-panel,
  .timeline-card,
  .project-quicklink,
  .skill-group,
  .competency-card,
  .stat-card {
    padding: 1rem;
  }

  .badge,
  .tag,
  .skill-group li {
    white-space: normal;
    text-align: center;
    justify-content: center;
  }

  .gallery-grid img {
    height: 170px;
  }

  .stat-card strong {
    font-size: 1.55rem;
  }




}

:root {
  --bg: #070b14;
  --bg-soft: #0d1320;
  --bg-card: rgba(16, 23, 38, 0.88);
  --bg-card-strong: #11192a;
  --text: #eff4ff;
  --text-soft: #c1cadb;
  --text-muted: #7f8aa3;
  --border: rgba(130, 152, 194, 0.18);
  --border-strong: rgba(0, 245, 212, 0.32);
  --cyan: #00f5d4;
  --violet: #9c8cff;
  --rose: #ff7b8d;
  --gold: #ffd166;
  --green: #44d7a8;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.36);
  --radius: 24px;
  --radius-small: 14px;
  --nav-height: 74px;
  --max-width: 1180px;
  --hero-gradient: linear-gradient(160deg, #101833 0%, #060913 52%, #0a1020 100%);
  --accent-gradient: linear-gradient(135deg, #00f5d4 0%, #9c8cff 56%, #ff7b8d 100%);
  --card-gradient: linear-gradient(135deg, rgba(0, 245, 212, 0.12), rgba(156, 140, 255, 0.08));
  --font-body: "Segoe UI", Arial, sans-serif;
  --tilt-x: 0deg;
  --tilt-y: 0deg;
  --bg-orb-1: rgba(0, 245, 212, 0.08);
  --bg-orb-2: rgba(156, 140, 255, 0.08);
  --surface-overlay: rgba(255, 255, 255, 0.04);
  --surface-overlay-strong: rgba(255, 255, 255, 0.06);
  --surface-outline: rgba(255, 255, 255, 0.12);
  --header-bg: rgba(7, 11, 20, 0.78);
  --header-bg-scrolled: rgba(7, 11, 20, 0.92);
  --title-gradient: linear-gradient(135deg, #ffffff 0%, #dce8ff 45%, #ffffff 100%);
  --hero-dot: rgba(255, 255, 255, 0.12);
  --hero-ring: rgba(255, 255, 255, 0.14);
  --shine-overlay: rgba(255, 255, 255, 0.22);
  --mobile-menu-bg: rgba(10, 15, 25, 0.96);
  --nav-link-hover-bg: rgba(255, 255, 255, 0.05);
  --footer-bg: linear-gradient(180deg, #090c18 0%, #04060e 100%);
  --footer-grid: rgba(255, 255, 255, 0.03);
  color-scheme: dark;
}

html[data-theme="light"] {
  --bg: #eef4fb;
  --bg-soft: #dfe9f6;
  --bg-card: rgba(255, 255, 255, 0.82);
  --bg-card-strong: #ffffff;
  --text: #132238;
  --text-soft: #314155;
  --text-muted: #64748b;
  --border: rgba(15, 23, 42, 0.12);
  --border-strong: rgba(0, 184, 162, 0.26);
  --cyan: #6d63ff;
  --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
  --hero-gradient: linear-gradient(160deg, #fbfdff 0%, #e9f2ff 52%, #f5f8fc 100%);
  --accent-gradient: linear-gradient(135deg, #00b8a2 0%, #6d63ff 56%, #ff5f7a 100%);
  --card-gradient: linear-gradient(135deg, rgba(0, 184, 162, 0.12), rgba(109, 99, 255, 0.08));
  --bg-orb-1: rgba(0, 184, 162, 0.12);
  --bg-orb-2: rgba(109, 99, 255, 0.12);
  --surface-overlay: rgba(15, 23, 42, 0.04);
  --surface-overlay-strong: rgba(15, 23, 42, 0.06);
  --surface-outline: rgba(15, 23, 42, 0.1);
  --header-bg: rgba(238, 244, 251, 0.82);
  --header-bg-scrolled: rgba(238, 244, 251, 0.96);
  --title-gradient: linear-gradient(135deg, #11223a 0%, #2f5f98 45%, #11223a 100%);
  --hero-dot: rgba(15, 23, 42, 0.08);
  --hero-ring: rgba(15, 23, 42, 0.12);
  --shine-overlay: rgba(255, 255, 255, 0.32);
  --mobile-menu-bg: rgba(255, 255, 255, 0.96);
  --nav-link-hover-bg: rgba(15, 23, 42, 0.06);
  --footer-bg: linear-gradient(180deg, #e9f1fb 0%, #dde8f8 100%);
  --footer-grid: rgba(15, 23, 42, 0.05);
  color-scheme: light;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  position: relative;
  font-family: var(--font-body);
  color: var(--text);
  background:
    radial-gradient(circle at top right, var(--bg-orb-1), transparent 28%),
    radial-gradient(circle at bottom left, var(--bg-orb-2), transparent 30%),
    var(--bg);
  line-height: 1.65;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 0.55s ease, transform 0.55s ease, background-color 0.3s ease, color 0.3s ease;
}

body::before,
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  z-index: 420;
}

body::before {
  background:
    radial-gradient(circle at 18% 26%, rgba(0, 245, 212, 0.24), transparent 28%),
    radial-gradient(circle at 78% 34%, rgba(156, 140, 255, 0.22), transparent 26%),
    radial-gradient(circle at 52% 74%, rgba(255, 123, 141, 0.18), transparent 24%),
    linear-gradient(115deg, transparent 30%, rgba(0, 245, 212, 0.08) 48%, transparent 66%);
  mix-blend-mode: screen;
  filter: blur(32px);
}

body::after {
  background:
    linear-gradient(90deg, transparent 0%, rgba(0, 245, 212, 0.14) 18%, transparent 36%),
    linear-gradient(90deg, transparent 26%, rgba(156, 140, 255, 0.1) 50%, transparent 74%),
    linear-gradient(90deg, transparent 58%, rgba(255, 123, 141, 0.1) 82%, transparent 100%);
}

body.is-theme-shifting::before {
  animation: themeMorphGlow 720ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

body.is-theme-shifting::after {
  animation: themeMorphSlices 680ms steps(2, end) both;
}

body.is-page-leaving::before,
body.is-page-arriving::before {
  animation: themeMorphGlow 760ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

body.is-page-leaving::after,
body.is-page-arriving::after {
  animation: pageMorphSlices 720ms steps(2, end) both;
}

body.is-theme-shifting .site-header,
body.is-theme-shifting .page-main,
body.is-theme-shifting .hero,
body.is-theme-shifting .footer {
  animation: themeSurfaceMorph 680ms cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: center;
  will-change: transform, filter, clip-path, opacity;
}

body.is-page-leaving {
  overflow: hidden;
}

body.is-page-leaving .site-header,
body.is-page-leaving .page-main,
body.is-page-leaving .hero,
body.is-page-leaving .footer {
  animation: pageGlitchOut 520ms cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: center;
  will-change: transform, filter, clip-path, opacity;
}

body.is-page-arriving .site-header,
body.is-page-arriving .page-main,
body.is-page-arriving .hero,
body.is-page-arriving .footer {
  animation: pageGlitchIn 760ms cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: center;
  will-change: transform, filter, clip-path, opacity;
}

@keyframes themeMorphGlow {
  0% {
    opacity: 0;
    transform: scale(0.96);
  }
  18% {
    opacity: 0.5;
    transform: scale(1.02) translate3d(-8px, 0, 0);
  }
  44% {
    opacity: 0.75;
    transform: scale(1.05) translate3d(10px, -4px, 0);
  }
  72% {
    opacity: 0.28;
    transform: scale(1.01) translate3d(-4px, 3px, 0);
  }
  100% {
    opacity: 0;
    transform: scale(1.08);
  }
}

@keyframes themeMorphSlices {
  0% {
    opacity: 0;
    clip-path: inset(0 0 100% 0);
    transform: translate3d(0, 0, 0);
  }
  24% {
    opacity: 0.45;
    clip-path: inset(8% 0 56% 0);
    transform: translate3d(-10px, 0, 0);
  }
  48% {
    opacity: 0.38;
    clip-path: inset(38% 0 18% 0);
    transform: translate3d(12px, 0, 0);
  }
  72% {
    opacity: 0.22;
    clip-path: inset(70% 0 8% 0);
    transform: translate3d(-8px, 0, 0);
  }
  100% {
    opacity: 0;
    clip-path: inset(100% 0 0 0);
    transform: translate3d(0, 0, 0);
  }
}

@keyframes pageMorphSlices {
  0% {
    opacity: 0;
    clip-path: inset(0 0 100% 0);
    transform: translate3d(0, 0, 0);
  }
  18% {
    opacity: 0.55;
    clip-path: inset(6% 0 68% 0);
    transform: translate3d(-14px, 0, 0);
  }
  40% {
    opacity: 0.44;
    clip-path: inset(28% 0 36% 0);
    transform: translate3d(16px, 0, 0);
  }
  62% {
    opacity: 0.34;
    clip-path: inset(56% 0 18% 0);
    transform: translate3d(-10px, 0, 0);
  }
  84% {
    opacity: 0.18;
    clip-path: inset(82% 0 6% 0);
    transform: translate3d(8px, 0, 0);
  }
  100% {
    opacity: 0;
    clip-path: inset(100% 0 0 0);
    transform: translate3d(0, 0, 0);
  }
}

@keyframes themeSurfaceMorph {
  0% {
    filter: saturate(1) blur(0);
    clip-path: inset(0 0 0 0 round 0);
    transform: translate3d(0, 0, 0) scale(1);
  }
  18% {
    filter: saturate(1.18) blur(1px);
    clip-path: inset(0.5% 0 1.2% 0 round 18px);
    transform: translate3d(-4px, 1px, 0) scale(1.003);
  }
  42% {
    filter: saturate(1.08) blur(1.8px);
    clip-path: inset(1.2% 0 0.4% 0 round 24px);
    transform: translate3d(5px, -2px, 0) scale(1.008);
  }
  68% {
    filter: saturate(1.02) blur(0.8px);
    clip-path: inset(0.4% 0 0.8% 0 round 16px);
    transform: translate3d(-2px, 1px, 0) scale(1.002);
  }
  100% {
    filter: saturate(1) blur(0);
    clip-path: inset(0 0 0 0 round 0);
    transform: translate3d(0, 0, 0) scale(1);
  }
}

@keyframes pageGlitchOut {
  0% {
    opacity: 1;
    filter: saturate(1) blur(0) drop-shadow(0 0 0 rgba(0, 245, 212, 0)) drop-shadow(0 0 0 rgba(255, 123, 141, 0));
    clip-path: inset(0 0 0 0 round 0);
    transform: translate3d(0, 0, 0) scale(1);
  }
  18% {
    opacity: 0.98;
    filter:
      saturate(1.18)
      blur(0.8px)
      drop-shadow(-4px 0 0 rgba(0, 245, 212, 0.18))
      drop-shadow(3px 0 0 rgba(255, 123, 141, 0.1));
    clip-path: inset(0.4% 0 1.8% 0 round 18px);
    transform: translate3d(-5px, 1px, 0) scale(1.003);
  }
  42% {
    opacity: 0.82;
    filter:
      saturate(1.28)
      blur(1.8px)
      drop-shadow(-8px 0 0 rgba(0, 245, 212, 0.34))
      drop-shadow(6px 0 0 rgba(255, 123, 141, 0.16));
    clip-path: inset(1.2% 0 4.4% 0 round 24px);
    transform: translate3d(8px, -3px, 0) scale(1.012);
  }
  72% {
    opacity: 0.36;
    filter:
      saturate(1.08)
      blur(2.4px)
      drop-shadow(-10px 0 0 rgba(0, 245, 212, 0.24))
      drop-shadow(7px 0 0 rgba(255, 123, 141, 0.12));
    clip-path: inset(6% 0 10% 0 round 32px);
    transform: translate3d(-10px, 3px, 0) scale(1.02);
  }
  100% {
    opacity: 0;
    filter:
      saturate(0.96)
      blur(4px)
      drop-shadow(-14px 0 0 rgba(0, 245, 212, 0.1))
      drop-shadow(10px 0 0 rgba(255, 123, 141, 0.06));
    clip-path: inset(14% 0 18% 0 round 42px);
    transform: translate3d(14px, -4px, 0) scale(1.03);
  }
}

@keyframes pageGlitchIn {
  0% {
    opacity: 0;
    filter:
      saturate(1.3)
      blur(4px)
      drop-shadow(-14px 0 0 rgba(0, 245, 212, 0.28))
      drop-shadow(10px 0 0 rgba(255, 123, 141, 0.14));
    clip-path: inset(16% 0 20% 0 round 42px);
    transform: translate3d(-14px, 5px, 0) scale(1.03);
  }
  24% {
    opacity: 0.42;
    filter:
      saturate(1.22)
      blur(2.4px)
      drop-shadow(-10px 0 0 rgba(0, 245, 212, 0.34))
      drop-shadow(7px 0 0 rgba(255, 123, 141, 0.16));
    clip-path: inset(7% 0 10% 0 round 30px);
    transform: translate3d(10px, -3px, 0) scale(1.018);
  }
  48% {
    opacity: 0.78;
    filter:
      saturate(1.12)
      blur(1.2px)
      drop-shadow(-7px 0 0 rgba(0, 245, 212, 0.26))
      drop-shadow(5px 0 0 rgba(255, 123, 141, 0.12));
    clip-path: inset(2.2% 0 4.2% 0 round 20px);
    transform: translate3d(-6px, 2px, 0) scale(1.008);
  }
  76% {
    opacity: 0.94;
    filter:
      saturate(1.04)
      blur(0.4px)
      drop-shadow(-3px 0 0 rgba(0, 245, 212, 0.12))
      drop-shadow(2px 0 0 rgba(255, 123, 141, 0.08));
    clip-path: inset(0.6% 0 1.2% 0 round 10px);
    transform: translate3d(3px, -1px, 0) scale(1.002);
  }
  100% {
    opacity: 1;
    filter: saturate(1) blur(0) drop-shadow(0 0 0 rgba(0, 245, 212, 0)) drop-shadow(0 0 0 rgba(255, 123, 141, 0));
    clip-path: inset(0 0 0 0 round 0);
    transform: translate3d(0, 0, 0) scale(1);
  }
}

body.is-ready {
  opacity: 1;
  transform: translateY(0);
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

p {
  margin: 0 0 1rem;
  color: var(--text-soft);
}

ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

h1,
h2,
h3,
h4 {
  margin: 0;
  line-height: 1.12;
}

.container {
  width: min(var(--max-width), calc(100% - 2rem));
  margin: 0 auto;
}

.section {
  padding: clamp(4.5rem, 8vw, 7rem) 0;
}

.section-header {
  margin-bottom: 2rem;
  max-width: 700px;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  margin-bottom: 0.9rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--cyan);
  transition: color 0.24s ease, transform 0.24s ease;
}

.eyebrow::before {
  content: "";
  width: 28px;
  height: 2px;
  border-radius: 999px;
  background: var(--accent-gradient);
  transition: transform 0.24s ease, filter 0.24s ease;
}

.eyebrow:hover {
  color: var(--violet);
  transform: translateX(2px);
}

.eyebrow:hover::before {
  transform: scaleX(1.08);
  filter: saturate(1.15) brightness(1.08);
}

.section-header h2 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  letter-spacing: -0.04em;
}

.section-header p {
  margin-top: 0.8rem;
  max-width: 60ch;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
}

.skip-link:focus {
  left: 1rem;
  top: 1rem;
  z-index: 500;
  padding: 0.75rem 1rem;
  border-radius: 10px;
  background: #fff;
  color: #000;
}

.site-header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 300;
  height: var(--nav-height);
  backdrop-filter: blur(18px);
  background: var(--header-bg);
  border-bottom: 1px solid transparent;
  transition: border-color 0.25s ease, background 0.25s ease;
}

.site-header.is-scrolled {
  border-bottom-color: var(--border);
  background: var(--header-bg-scrolled);
}

.nav {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.nav > nav {
  margin-left: auto;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
  font-weight: 700;
  transition: transform 0.22s ease;
}

.brand:hover {
  transform: translateY(-2px);
}

.brand__mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 56px;
  height: 42px;
  padding: 0 0.7rem;
  border-radius: 14px;
  background: var(--surface-overlay);
  border: 1px solid var(--surface-outline);
  background-image: var(--accent-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  font-size: 0.98rem;
  font-weight: 800;
  letter-spacing: -0.05em;
  line-height: 1;
  white-space: nowrap;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}

.brand:hover .brand__mark {
  transform: rotate(-6deg) scale(1.04);
  box-shadow: 0 14px 26px rgba(0, 245, 212, 0.16);
  border-color: rgba(0, 245, 212, 0.24);
}

.brand__text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.brand__name {
  font-size: 0.98rem;
}

.brand__role {
  font-size: 0.74rem;
  color: var(--text-muted);
  font-weight: 500;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.nav__link {
  position: relative;
  font-size: 0.96rem;
  font-weight: 600;
  color: var(--text-soft);
  transition: color 0.2s ease, transform 0.2s ease;
}

.nav__link::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -0.35rem;
  width: 100%;
  height: 2px;
  border-radius: 999px;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.22s ease;
  background: var(--accent-gradient);
}

.nav__link:hover,
.nav__link[aria-current="page"] {
  color: var(--text);
  transform: translateY(-1px);
}

.nav__link:hover::after,
.nav__link[aria-current="page"]::after {
  transform: scaleX(1);
}

.nav__toggle {
  display: none;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface-overlay);
  cursor: pointer;
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex-shrink: 0;
}

.theme-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 34px;
  padding: 0.18rem 0.45rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  opacity: 0.82;
  transition: background 0.2s ease, border-color 0.2s ease, opacity 0.2s ease;
}

.theme-toggle:hover {
  border-color: var(--border);
  background: var(--surface-overlay);
  opacity: 1;
}

.theme-toggle__track {
  position: relative;
  width: 30px;
  height: 16px;
  border-radius: 999px;
  background: var(--surface-overlay);
  box-shadow: inset 0 0 0 1px var(--border);
  overflow: hidden;
  transition: background 0.28s ease, box-shadow 0.28s ease;
}

.theme-toggle__track::before,
.theme-toggle__track::after {
  position: absolute;
  top: 50%;
  font-size: 0.52rem;
  line-height: 1;
  color: var(--text-soft);
  transform: translateY(-50%);
  transition: opacity 0.28s ease, transform 0.32s cubic-bezier(0.22, 1, 0.36, 1), color 0.28s ease;
}

.theme-toggle__track::before {
  content: "\2600";
  left: 3px;
  opacity: 0;
  transform: translateY(-50%) scale(0.78);
}

.theme-toggle__track::after {
  content: "\263E";
  right: 3px;
  opacity: 1;
  transform: translateY(-50%) scale(1);
}

.theme-toggle__thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text);
  box-shadow: none;
  transition: transform 0.32s cubic-bezier(0.22, 1, 0.36, 1), background 0.28s ease;
}

html[data-theme="light"] .theme-toggle__thumb {
  transform: translateX(14px);
  background: var(--violet);
}

.theme-toggle__text {
  display: none;
}

html[data-theme="light"] .theme-toggle__track::before {
  opacity: 1;
  transform: translateY(-50%) scale(1);
  color: var(--violet);
}

html[data-theme="light"] .theme-toggle__track::after {
  opacity: 0;
  transform: translateY(-50%) scale(0.78);
}

.nav__toggle span {
  display: block;
  width: 20px;
  height: 2px;
  margin: 5px auto;
  background: var(--text);
  border-radius: 999px;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

.nav__toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.nav__toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.nav__toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.page-main {
  padding-top: var(--nav-height);
}

.hero {
  position: relative;
  overflow: hidden;
  background: var(--hero-gradient);
}

.hero::before,
.hero::after {
  content: "";
  position: absolute;
  border-radius: 999px;
  filter: blur(80px);
  pointer-events: none;
  animation: heroGlow 14s ease-in-out infinite alternate;
}

.hero__inner::before,
.page-hero__inner::before {
  content: "";
  position: absolute;
  inset: 8% 18% auto auto;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background:
    radial-gradient(circle, var(--hero-dot) 0 4%, transparent 4% 100%),
    radial-gradient(circle, rgba(0, 245, 212, 0.18), transparent 66%);
  opacity: 0.5;
  filter: blur(2px);
  animation: beaconFloat 10s ease-in-out infinite alternate;
  pointer-events: none;
}

.hero__inner::after,
.page-hero__inner::after {
  content: "";
  position: absolute;
  inset: auto auto 10% 4%;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  border: 1px dashed var(--hero-ring);
  opacity: 0.4;
  animation: spinHalo 24s linear infinite;
  pointer-events: none;
}

.hero::before {
  width: 360px;
  height: 360px;
  top: -80px;
  right: -40px;
  background: rgba(0, 245, 212, 0.16);
}

.hero::after {
  width: 320px;
  height: 320px;
  bottom: -100px;
  left: -60px;
  background: rgba(156, 140, 255, 0.16);
  animation-delay: -6s;
}

@keyframes heroGlow {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }
  to {
    transform: translate3d(20px, 24px, 0) scale(1.08);
  }
}

@keyframes beaconFloat {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }
  to {
    transform: translate3d(-28px, 18px, 0) scale(1.08);
  }
}

@keyframes spinHalo {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.hero__inner,
.page-hero__inner {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(280px, 0.75fr);
  gap: 2rem;
  align-items: center;
  min-height: calc(100vh - var(--nav-height));
  padding: 4rem 0 3rem;
  position: relative;
  z-index: 1;
}

.hero__content h1,
.page-hero__content h1 {
  font-size: clamp(3rem, 6vw, 5.6rem);
  letter-spacing: -0.06em;
}

.hero__content,
.page-hero__content {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.75s ease, transform 0.75s ease;
}

.hero__content h1,
.page-hero__content h1,
.section-header h2 {
  background: var(--title-gradient);
  background-size: 180% auto;
  -webkit-background-clip: text;
  background-clip: text;
  animation: titleSheen 7s linear infinite;
}

.hero-name-hover {
  display: inline-block;
  cursor: default;
  user-select: none;
  position: relative;
  isolation: isolate;
}

.hero-name-hover::before {
  content: "";
  position: absolute;
  inset: -8px;
  background: linear-gradient(
    110deg,
    transparent 0%,
    transparent 44%,
    var(--shine-overlay) 50%,
    transparent 56%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: nameShine 9s linear infinite;
  pointer-events: none;
  z-index: 2;
  mix-blend-mode: screen;
  filter: blur(14px);
  opacity: 0.55;
}

@keyframes nameShine {
  0% {
    background-position: 200% center;
  }
  100% {
    background-position: -200% center;
  }
}

.hero-name-hover::after {
  content: none;
}

.hero-name-hover span {
  display: inline-block;
  position: relative;
  isolation: isolate;
  transition:
    transform 0.18s ease,
    text-shadow 0.35s ease,
    filter 0.35s ease;
  text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
}

.hero-name-hover span::before,
.hero-name-hover span::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  mix-blend-mode: screen;
  transition: opacity 0.18s ease;
}

.hero-name-hover span::before {
  color: rgba(0, 245, 212, 0.9);
  text-shadow: -0.03em 0 0 rgba(0, 245, 212, 0.5);
}

.hero-name-hover span::after {
  color: rgba(255, 123, 141, 0.9);
  text-shadow: 0.03em 0 0 rgba(255, 123, 141, 0.45);
}

.hero-name-hover:hover span {
  filter: brightness(1.03);
}

.hero-name-hover:hover span:first-child {
  animation: nameGlitchPrimary 460ms steps(2, end) 1;
}

.hero-name-hover:hover span:last-child {
  animation: nameGlitchSecondary 520ms steps(2, end) 1;
}

.hero-name-hover:hover span::before,
.hero-name-hover:hover span::after {
  opacity: 0.72;
}

.hero-name-hover:hover span::before {
  animation: glitchLayerCyan 460ms steps(2, end) 1;
}

.hero-name-hover:hover span::after {
  animation: glitchLayerRose 520ms steps(2, end) 1;
}

.glitch-title {
  display: inline-block;
  cursor: default;
  position: relative;
  isolation: isolate;
}

.glitch-title span {
  display: inline-block;
  position: relative;
  isolation: isolate;
  transition:
    transform 0.18s ease,
    text-shadow 0.35s ease,
    filter 0.35s ease;
  text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
}

.glitch-title span::before,
.glitch-title span::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  mix-blend-mode: screen;
  transition: opacity 0.18s ease;
}

.glitch-title span::before {
  color: rgba(0, 245, 212, 0.9);
  text-shadow: -0.03em 0 0 rgba(0, 245, 212, 0.5);
}

.glitch-title span::after {
  color: rgba(255, 123, 141, 0.9);
  text-shadow: 0.03em 0 0 rgba(255, 123, 141, 0.45);
}

.glitch-title:hover span {
  filter: brightness(1.03);
  animation: nameGlitchPrimary 460ms steps(2, end) 1;
}

.glitch-title:hover span::before,
.glitch-title:hover span::after {
  opacity: 0.72;
}

.glitch-title:hover span::before {
  animation: glitchLayerCyan 460ms steps(2, end) 1;
}

.glitch-title:hover span::after {
  animation: glitchLayerRose 520ms steps(2, end) 1;
}

.about-title-special {
  display: inline-block;
  position: relative;
  isolation: isolate;
  transition:
    transform 0.28s ease,
    text-shadow 0.28s ease,
    letter-spacing 0.28s ease,
    filter 0.28s ease;
}

.about-title-special::before {
  content: "";
  position: absolute;
  inset: auto -0.15em -0.08em;
  height: 0.45em;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(0, 245, 212, 0.2), rgba(156, 140, 255, 0.28), rgba(255, 123, 141, 0.18));
  filter: blur(10px);
  opacity: 0;
  transform: scaleX(0.3);
  transform-origin: center;
  transition: opacity 0.28s ease, transform 0.4s ease;
  z-index: -1;
}

.about-title-special::after {
  content: "";
  position: absolute;
  left: -0.02em;
  right: -0.02em;
  bottom: -0.14em;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--cyan), var(--violet), var(--rose));
  transform: scaleX(0.22);
  transform-origin: left;
  transition: transform 0.38s ease;
}

.about-title-special:hover {
  transform: translateY(-2px) skewX(-4deg);
  letter-spacing: 0.015em;
  filter: brightness(1.04);
  text-shadow:
    -0.04em 0 0 rgba(0, 245, 212, 0.42),
    0.04em 0 0 rgba(156, 140, 255, 0.42),
    0 12px 24px rgba(6, 10, 18, 0.28);
}

.about-title-special:hover::before {
  opacity: 1;
  transform: scaleX(1);
}

.about-title-special:hover::after {
  transform: scaleX(1);
}

.about-hero-title {
  display: inline-block;
  position: relative;
  isolation: isolate;
  transition:
    transform 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    text-shadow 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    letter-spacing 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  text-shadow: 0 10px 24px rgba(6, 10, 18, 0.22);
}

.about-hero-title::before {
  content: "";
  position: absolute;
  inset: -0.12em -0.18em;
  border-radius: 0.28em;
  background:
    linear-gradient(
      115deg,
      transparent 0%,
      transparent 18%,
      rgba(0, 245, 212, 0.22) 28%,
      rgba(156, 140, 255, 0.26) 48%,
      rgba(255, 123, 141, 0.2) 68%,
      transparent 82%,
      transparent 100%
    );
  background-size: 220% 100%;
  opacity: 0;
  filter: blur(10px);
  transform: translateX(-16%) skewX(-14deg);
  transition:
    opacity 0.45s ease,
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    background-position 0.95s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: -2;
}

.about-hero-title::after {
  content: "";
  position: absolute;
  left: 0.02em;
  right: 0.02em;
  top: 54%;
  height: 0.42em;
  border-radius: 0.08em;
  background:
    linear-gradient(90deg, rgba(0, 245, 212, 0.22), rgba(156, 140, 255, 0.28), rgba(255, 123, 141, 0.2));
  opacity: 0;
  transform: scaleX(0.08) skewX(-24deg);
  transform-origin: left;
  filter: blur(5px);
  transition:
    opacity 0.4s ease,
    transform 0.75s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: -1;
}

.about-hero-title:hover {
  transform: translateY(-2px) scale(1.012);
  filter: brightness(1.05);
  letter-spacing: 0.012em;
  text-shadow:
    -0.016em 0 0 rgba(0, 245, 212, 0.32),
    0.016em 0 0 rgba(156, 140, 255, 0.32),
    0.045em 0 0 rgba(255, 123, 141, 0.18),
    0 14px 30px rgba(6, 10, 18, 0.34);
}

.about-hero-title:hover::before {
  opacity: 1;
  background-position: 100% 0;
  transform: translateX(4%) skewX(-14deg);
}

.about-hero-title:hover::after {
  opacity: 1;
  transform: scaleX(1) skewX(-24deg);
}

@keyframes nameGlitchPrimary {
  0% {
    transform: translate3d(0, 0, 0);
    text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
  }
  20% {
    transform: translate3d(-2px, 1px, 0);
  }
  40% {
    transform: translate3d(2px, -1px, 0);
    text-shadow:
      -0.05em 0 0 rgba(0, 245, 212, 0.5),
      0.05em 0 0 rgba(255, 123, 141, 0.35),
      0 10px 22px rgba(6, 10, 18, 0.24);
  }
  60% {
    transform: translate3d(-1px, 1px, 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
    text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
  }
}

@keyframes nameGlitchSecondary {
  0% {
    transform: translate3d(0, 0, 0);
    text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
  }
  18% {
    transform: translate3d(2px, 0, 0);
  }
  38% {
    transform: translate3d(-3px, 1px, 0);
    text-shadow:
      -0.04em 0 0 rgba(255, 123, 141, 0.42),
      0.04em 0 0 rgba(0, 245, 212, 0.42),
      0 10px 22px rgba(6, 10, 18, 0.24);
  }
  58% {
    transform: translate3d(1px, -1px, 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
    text-shadow: 0 8px 18px rgba(6, 10, 18, 0.2);
  }
}

@keyframes glitchLayerCyan {
  0% {
    transform: translate3d(0, 0, 0);
    clip-path: inset(0 0 0 0);
  }
  25% {
    transform: translate3d(-4px, 0, 0);
    clip-path: inset(8% 0 55% 0);
  }
  50% {
    transform: translate3d(3px, -1px, 0);
    clip-path: inset(48% 0 18% 0);
  }
  75% {
    transform: translate3d(-2px, 1px, 0);
    clip-path: inset(72% 0 4% 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
    clip-path: inset(0 0 0 0);
  }
}

@keyframes glitchLayerRose {
  0% {
    transform: translate3d(0, 0, 0);
    clip-path: inset(0 0 0 0);
  }
  20% {
    transform: translate3d(4px, 0, 0);
    clip-path: inset(14% 0 52% 0);
  }
  45% {
    transform: translate3d(-3px, 1px, 0);
    clip-path: inset(56% 0 12% 0);
  }
  70% {
    transform: translate3d(2px, -1px, 0);
    clip-path: inset(34% 0 36% 0);
  }
  100% {
    transform: translate3d(0, 0, 0);
    clip-path: inset(0 0 0 0);
  }
}

@keyframes titleSheen {
  from {
    background-position: 0% center;
  }
  to {
    background-position: 180% center;
  }
}

.hero-card {
  opacity: 0;
  transform: translateY(28px) scale(0.985);
  transition:
    opacity 0.8s ease,
    transform 0.8s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

body.is-ready .hero__content,
body.is-ready .page-hero__content,
body.is-ready .hero-card {
  opacity: 1;
  transform: translateY(0) scale(1);
}

body.is-ready .hero-card {
  transition-delay: 0.12s;
}

.hero__content p.lead,
.page-hero__content p.lead {
  max-width: 58ch;
  margin-top: 1.2rem;
  font-size: 1.08rem;
}

.hero__welcome {
  margin: 1.5rem 0 2rem;
  padding: 1rem 1.1rem;
  border: 1px solid rgba(0, 245, 212, 0.18);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
  max-width: 34rem;
  transition: transform 0.25s ease, border-color 0.25s ease, background 0.25s ease;
}

.hero__welcome:hover {
  transform: translateY(-2px);
  border-color: rgba(0, 245, 212, 0.3);
  background: rgba(255, 255, 255, 0.06);
}

.hero__actions,
.action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0.85rem 1.3rem;
  border-radius: 14px;
  font-weight: 700;
  border: 1px solid transparent;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
  cursor: pointer;
}

.btn:hover {
  transform: translateY(-2px) scale(1.02);
  animation: magneticPulse 0.6s ease;
}

@keyframes magneticPulse {
  0% {
    box-shadow: 0 0 0 0 rgba(0, 245, 212, 0.4);
  }
  50% {
    box-shadow: 0 0 0 10px rgba(0, 245, 212, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(0, 245, 212, 0);
  }
}

.btn::after {
  content: "";
  position: absolute;
  inset: -120% auto -120% -30%;
  width: 42%;
  transform: rotate(18deg) translateX(-180%);
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.28), transparent);
  transition: transform 0.6s ease;
}

.btn:hover::after {
  transform: rotate(18deg) translateX(520%);
}

.btn--primary {
  background: linear-gradient(135deg, #00f5d4, #00c4a7);
  color: #041017;
  box-shadow: 0 12px 30px rgba(0, 245, 212, 0.18);
}

.btn--secondary {
  background: var(--surface-overlay-strong);
  border-color: var(--border);
}

.btn--primary:hover {
  box-shadow: 0 18px 36px rgba(0, 245, 212, 0.24);
}

.btn--secondary:hover {
  border-color: rgba(156, 140, 255, 0.26);
  background: rgba(156, 140, 255, 0.08);
}

.hero-card,
.panel,
.card,
.project-card,
.timeline-card,
.competency-card,
.cv-panel,
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
  transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, transform 0.3s ease;
}

.hero-card {
  border-radius: 28px;
  padding: 1.5rem;
  position: relative;
  overflow: hidden;
  transform-style: preserve-3d;
}

.hero-card::before,
.panel::before,
.card::before,
.project-quicklink::before,
.project-card::before,
.competency-card::before,
.cv-panel::before,
.feature-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0, 245, 212, 0.1), transparent 35%, rgba(156, 140, 255, 0.08));
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.hero-card::after,
.panel::after,
.card::after,
.project-quicklink::after,
.project-card::after,
.competency-card::after,
.cv-panel::after,
.feature-card::after {
  content: none;
}

.hero-card:hover::before,
.panel:hover::before,
.card:hover::before,
.project-quicklink:hover::before,
.project-card:hover::before,
.competency-card:hover::before,
.cv-panel:hover::before,
.feature-card:hover::before {
  opacity: 1;
}

.hero-card__photo {
  aspect-ratio: 4 / 5;
  overflow: hidden;
  border-radius: 22px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transform: translateZ(0);
}

.hero-card__photo--interactive {
  position: relative;
  cursor: pointer;
  isolation: isolate;
}

.hero-card__photo--interactive:focus-visible {
  outline: 2px solid rgba(0, 245, 212, 0.8);
  outline-offset: 4px;
}

.hero-card__photo-burst {
  position: absolute;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border-radius: 50%;
  pointer-events: none;
  z-index: 3;
  animation: fireworkBurst 850ms ease-out forwards;
}

.hero-card__photo-spark {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 4px;
  height: 24px;
  margin-left: -2px;
  margin-top: -22px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), currentColor 70%, rgba(255, 255, 255, 0));
  transform-origin: 50% 100%;
  animation: fireworkSpark 850ms ease-out forwards;
}

@keyframes fireworkBurst {
  0% {
    transform: scale(0.2);
    opacity: 0;
  }
  18% {
    opacity: 1;
  }
  100% {
    transform: scale(1.05);
    opacity: 0;
  }
}

@keyframes fireworkSpark {
  0% {
    transform: rotate(var(--angle)) translateY(0) scaleY(0.4);
    opacity: 1;
  }
  100% {
    transform: rotate(var(--angle)) translateY(calc(var(--distance) * -1)) scaleY(1.05);
    opacity: 0;
  }
}

.hero-card__photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.7s ease, filter 0.35s ease;
}

.hero-card:hover .hero-card__photo img {
  transform: scale(1.045);
  filter: saturate(1.06);
}

.hero-card__meta {
  display: grid;
  gap: 0.8rem;
  margin-top: 1rem;
}

.meta-pill {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.9rem 1rem;
  border-radius: 16px;
  background: var(--surface-overlay);
  transition: transform 0.22s ease, background 0.22s ease;
}

.hero-card:hover .meta-pill {
  transform: translateX(4px);
  background: var(--surface-overlay-strong);
}

.meta-pill span:first-child {
  color: var(--text-muted);
  font-size: 0.84rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.meta-pill strong {
  display: block;
  font-size: 0.95rem;
}

.grid-two,
.grid-three,
.skills-grid,
.projects-overview,
.competency-grid,
.cv-grid,
.gallery-grid,
.details-grid,
.hobby-grid,
.contact-grid {
  display: grid;
  gap: 1.25rem;
}

.grid-two,
.details-grid,
.cv-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid-three,
.skills-grid,
.projects-overview,
.competency-grid,
.gallery-grid,
.hobby-grid,
.contact-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.panel,
.card,
.feature-card,
.cv-panel {
  border-radius: var(--radius);
  padding: 1.5rem;
  position: relative;
  overflow: hidden;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease, background 0.24s ease;
}

.panel:hover,
.card:hover,
.feature-card:hover,
.cv-panel:hover,
.competency-card:hover,
.project-quicklink:hover {
  transform: translateY(-8px) rotateX(0.8deg) rotateY(-0.8deg);
  border-color: rgba(0, 245, 212, 0.22);
  box-shadow: 0 28px 52px rgba(0, 0, 0, 0.32);
}

.card h3,
.feature-card h3,
.cv-panel h3,
.timeline-card h3,
.project-card h3 {
  font-size: 1.25rem;
  letter-spacing: -0.03em;
  margin-bottom: 0.75rem;
}

.feature-card--identity {
  isolation: isolate;
  background:
    radial-gradient(circle at 85% 15%, rgba(0, 245, 212, 0.1), transparent 28%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.02));
}

.feature-card--identity::after {
  content: "";
  position: absolute;
  inset: -35%;
  background:
    conic-gradient(
      from 0deg,
      transparent 0deg,
      rgba(0, 245, 212, 0.3) 60deg,
      rgba(156, 140, 255, 0.38) 140deg,
      rgba(255, 123, 141, 0.28) 220deg,
      transparent 300deg
    );
  opacity: 0;
  filter: blur(28px);
  transform: scale(0.75) rotate(0deg);
  transition: opacity 0.35s ease, transform 0.7s ease;
  pointer-events: none;
  z-index: 0;
}

.feature-card--identity > * {
  position: relative;
  z-index: 1;
}

.feature-card--identity h3 {
  transition: transform 0.35s ease, letter-spacing 0.35s ease, text-shadow 0.35s ease;
}

.feature-card--identity p {
  transition: transform 0.35s ease, color 0.35s ease;
}

.feature-card--identity:hover {
  transform: translateY(-10px) rotateX(2deg) rotateY(-2deg) scale(1.015);
  border-color: rgba(156, 140, 255, 0.3);
  box-shadow:
    0 30px 56px rgba(0, 0, 0, 0.34),
    0 0 0 1px rgba(156, 140, 255, 0.12);
}

.feature-card--identity:hover::after {
  opacity: 1;
  transform: scale(1) rotate(120deg);
}

.feature-card--identity:hover h3 {
  transform: translateX(6px);
  letter-spacing: 0.01em;
  text-shadow:
    -0.04em 0 0 rgba(0, 245, 212, 0.45),
    0.04em 0 0 rgba(156, 140, 255, 0.4),
    0 10px 24px rgba(6, 10, 18, 0.3);
}

.feature-card--identity:hover p {
  transform: translateX(3px);
  color: var(--text);
}

.list {
  display: grid;
  gap: 0.7rem;
}

.list li {
  position: relative;
  padding-left: 1rem;
  color: var(--text-soft);
}

.list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.7rem;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--cyan);
}

.project-section-header {
  margin-top: 3rem;
}

.project-section-header:first-of-type {
  margin-top: 1.2rem;
}

#project-list .skills-grid {
  /* enforce exact 50/50 columns for hard / soft skills */
  grid-template-columns: 1fr 1fr;
}

/* Make all direct children of two-column grids align to start to avoid vertical stretching */
.grid-two > * {
  align-self: start;
}

#semester-2 .grid-two > .card {
  align-self: start;
}

.project-image {
  width: 100%;
  margin-bottom: 1rem;
  border-radius: 14px;
  border: 1px solid var(--border);
}

.skill-group {
  border-radius: var(--radius);
  padding: 1.5rem;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
  border: 1px solid var(--border);
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.skill-group:hover {
  transform: translateY(-8px) rotateX(0.7deg);
  border-color: rgba(156, 140, 255, 0.24);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.28);
}

.skill-group ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin-top: 1rem;
}

.skill-group li,
.tag {
  display: inline-flex;
  align-items: center;
  padding: 0.5rem 0.8rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--text-soft);
  font-size: 0.92rem;
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, color 0.18s ease;
}

.skill-group li:hover,
.tag:hover {
  transform: translateY(-2px);
  border-color: rgba(0, 245, 212, 0.24);
  background: rgba(0, 245, 212, 0.08);
  color: var(--text);
}

.project-quicklink {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1.5rem;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
  position: relative;
  overflow: hidden;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.project-quicklink--featured {
  background:
    radial-gradient(circle at top right, rgba(255, 209, 102, 0.14), transparent 34%),
    linear-gradient(135deg, rgba(255, 123, 141, 0.1), rgba(156, 140, 255, 0.12) 46%, rgba(0, 245, 212, 0.08));
  border-color: rgba(255, 209, 102, 0.18);
}

.project-quicklink__eyebrow {
  display: inline-flex;
  margin-bottom: 0.55rem;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold);
}

.project-quicklink__meta {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.project-quicklink--featured .project-summary {
  max-width: 42ch;
}

.project-quicklink:hover {
  transform: translateY(-8px) scale(1.01);
  border-color: rgba(156, 140, 255, 0.24);
  box-shadow: 0 26px 52px rgba(0, 0, 0, 0.3);
}

.project-quicklink__top {
  position: relative;
  z-index: 1;
}

.project-summary,
.project-quicklink .link-arrow {
  position: relative;
  z-index: 1;
}

.project-quicklink__top {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
  flex-wrap: wrap;
}

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  width: fit-content;
  min-height: 2rem;
  padding: 0.5rem 0.85rem;
  border-radius: 999px;
  font-size: 0.76rem;
  line-height: 1.1;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
  white-space: nowrap;
  flex-shrink: 0;
  position: relative;
  transition: transform 0.2s ease;
}

.badge:hover {
  animation: glitchBadge 0.5s ease;
}

@keyframes glitchBadge {
  0%, 100% {
    transform: translate(0);
  }
  20% {
    transform: translate(-2px, 2px);
  }
  40% {
    transform: translate(2px, -2px);
  }
  60% {
    transform: translate(-1px, -1px);
  }
  80% {
    transform: translate(1px, 1px);
  }
}

.badge--cyan {
  color: var(--cyan);
  background: rgba(0, 245, 212, 0.1);
}

.badge--violet {
  color: var(--violet);
  background: rgba(156, 140, 255, 0.1);
}

.badge--rose {
  color: var(--rose);
  background: rgba(255, 123, 141, 0.1);
}

.badge--green {
  color: var(--green);
  background: rgba(68, 215, 168, 0.12);
}

.badge--gold {
  color: var(--gold);
  background: rgba(255, 209, 102, 0.1);
}

/* Unique award badge styling */
.award-badge {
  display: inline-block;
  margin-top: 0.7rem;
  position: relative;
}

.award-badge__inner {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.15rem;
  padding: 0.5rem 0.8rem 0.5rem 1.1rem;
  background: linear-gradient(135deg, rgba(255, 209, 102, 0.08) 0%, rgba(255, 209, 102, 0.04) 100%);
  border: 1px solid rgba(255, 209, 102, 0.18);
  border-left: 3px solid var(--gold);
  border-radius: 4px;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
  cursor: default;
}

.award-badge__inner::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.15) 50%, transparent 100%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}

.award-badge__label {
  display: block;
  font-size: 0.55rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 500;
  opacity: 0.68;
  line-height: 1;
}

.award-badge__label--strong {
  font-size: 0.64rem;
  font-weight: 700;
  opacity: 0.88;
  letter-spacing: 0.14em;
}

.award-badge:hover .award-badge__inner {
  background: linear-gradient(135deg, rgba(255, 209, 102, 0.12) 0%, rgba(255, 209, 102, 0.06) 100%);
  border-color: rgba(255, 209, 102, 0.28);
  box-shadow: 0 4px 12px rgba(255, 209, 102, 0.12);
}

.award-badge:hover .award-badge__inner::before {
  animation: glossSlide 0.6s ease;
}

@keyframes glossSlide {
  0% {
    opacity: 0;
    transform: translateX(-100%);
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateX(100%);
  }
}

.project-summary {
  color: var(--text-soft);
}

.link-arrow {
  color: var(--cyan);
  font-weight: 700;
  transition: letter-spacing 0.18s ease, color 0.18s ease;
}

.project-quicklink:hover .link-arrow,
.footer__col ul a:hover,
.footer__contact-value:hover {
  letter-spacing: 0.02em;
}

.timeline {
  display: grid;
  gap: 1rem;
}

.timeline-card {
  border-radius: var(--radius);
  padding: 1.5rem;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.timeline-card:hover {
  transform: translateX(12px) scale(1.01);
  border-color: rgba(0, 245, 212, 0.2);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.28);
}

.timeline-card__year {
  display: inline-block;
  margin-bottom: 0.8rem;
  color: var(--cyan);
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
}

.project-card {
  border-radius: 28px;
  padding: 1.7rem;
  margin-bottom: 1.5rem;
  position: relative;
  overflow: hidden;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.project-card:hover {
  transform: translateY(-10px) scale(1.004);
  border-color: rgba(0, 245, 212, 0.22);
  box-shadow: 0 30px 56px rgba(0, 0, 0, 0.34);
}

.chez-showcase {
  position: relative;
  overflow: hidden;
  margin-bottom: 1.5rem;
  padding: clamp(1.25rem, 3vw, 2rem);
  border: 1px solid rgba(255, 209, 102, 0.18);
  border-radius: 28px;
  background:
    linear-gradient(135deg, rgba(255, 209, 102, 0.11), transparent 28%),
    radial-gradient(circle at 88% 12%, rgba(0, 245, 212, 0.14), transparent 30%),
    radial-gradient(circle at 14% 86%, rgba(156, 140, 255, 0.16), transparent 34%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.018));
  box-shadow: 0 28px 64px rgba(0, 0, 0, 0.28);
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.chez-showcase::before {
  content: "";
  position: absolute;
  inset: -1px;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.13) 50%, transparent 100%),
    linear-gradient(rgba(255, 255, 255, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.035) 1px, transparent 1px);
  background-size: 220% 100%, 42px 42px, 42px 42px;
  opacity: 0.42;
  transform: translateX(-18%);
  transition: transform 0.8s ease, opacity 0.3s ease;
}

.chez-showcase:hover {
  transform: translateY(-10px) scale(1.002);
  border-color: rgba(255, 209, 102, 0.3);
  box-shadow: 0 34px 70px rgba(0, 0, 0, 0.35);
}

.chez-showcase:hover::before {
  opacity: 0.7;
  transform: translateX(0);
}

.chez-showcase__intro,
.chez-showcase__stage,
.chez-showcase__workflow,
.chez-showcase__reflection {
  position: relative;
  z-index: 1;
}

.chez-showcase__intro {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(280px, 0.75fr);
  gap: 1.5rem;
  align-items: end;
  margin-bottom: 1.6rem;
}

.chez-showcase__intro h2 {
  max-width: 12ch;
  font-size: clamp(2rem, 4vw, 4rem);
  letter-spacing: -0.055em;
}

.chez-showcase__intro p {
  margin: 0;
  font-size: 1.02rem;
}

.chez-showcase__stage {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(300px, 0.7fr);
  gap: 1.2rem;
  align-items: stretch;
}

.chez-showcase__visual {
  position: relative;
  min-height: 480px;
  overflow: hidden;
  border-radius: 26px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background:
    linear-gradient(135deg, rgba(7, 11, 20, 0.16), rgba(7, 11, 20, 0.78)),
    rgba(8, 12, 22, 0.86);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 24px 48px rgba(0, 0, 0, 0.22);
}

.chez-showcase__visual img {
  width: 100%;
  height: 100%;
  min-height: 480px;
  object-fit: contain;
  object-position: center top;
  display: block;
  filter: saturate(1.04) contrast(1.02);
  transition: transform 0.7s ease, filter 0.35s ease;
}

.chez-showcase:hover .chez-showcase__visual img {
  transform: scale(1.025);
  filter: saturate(1.12) contrast(1.04);
}

.chez-showcase__pin {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 0.72rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(7, 11, 20, 0.78);
  color: var(--text);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  backdrop-filter: blur(14px);
  box-shadow: 0 16px 34px rgba(0, 0, 0, 0.28);
}

.chez-showcase__pin::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--gold);
  box-shadow: 0 0 0 5px rgba(255, 209, 102, 0.14);
}

.chez-showcase__pin--rooms {
  left: 1.2rem;
  top: 1.2rem;
}

.chez-showcase__pin--booking {
  right: 1.2rem;
  top: 48%;
}

.chez-showcase__pin--client {
  left: 1.2rem;
  bottom: 1.2rem;
}

.chez-showcase__brief {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.95rem;
  padding: 1.35rem;
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.045);
}

.chez-showcase__brief-top,
.chez-showcase__workflow {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.chez-showcase__brief h3 {
  font-size: clamp(1.4rem, 2.4vw, 2.1rem);
  letter-spacing: -0.04em;
}

.chez-showcase__brief p:last-child,
.chez-showcase__workflow p,
.chez-showcase__reflection p {
  margin-bottom: 0;
}

.chez-showcase__workflow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 1rem;
  counter-reset: chez-step;
}

.chez-showcase__workflow section {
  min-height: 185px;
  padding: 1rem;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(255, 255, 255, 0.04);
  transition: transform 0.22s ease, border-color 0.22s ease, background 0.22s ease;
}

.chez-showcase__workflow section:hover {
  transform: translateY(-6px);
  border-color: rgba(0, 245, 212, 0.22);
  background: rgba(0, 245, 212, 0.06);
}

.chez-showcase__workflow span {
  display: inline-flex;
  margin-bottom: 0.8rem;
  color: var(--gold);
  font-weight: 800;
  letter-spacing: 0.12em;
}

.chez-showcase__workflow h4,
.chez-showcase__reflection h4 {
  margin-bottom: 0.55rem;
}

.chez-showcase__reflection {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.chez-showcase__reflection > div {
  padding: 1.2rem;
  border-left: 3px solid var(--gold);
  border-radius: 0 18px 18px 0;
  background: rgba(255, 209, 102, 0.065);
}

.project-card__header {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.project-card__hero {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(320px, 0.95fr);
  gap: 1.4rem;
  align-items: center;
  width: 100%;
}

.project-card__hero-copy {
  display: grid;
  gap: 0.9rem;
}

.project-card__eyebrow {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 0.55rem;
  padding: 0.35rem 0.8rem;
  border-radius: 999px;
  background: rgba(255, 209, 102, 0.12);
  border: 1px solid rgba(255, 209, 102, 0.16);
  color: var(--gold);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.project-card__hero-side {
  display: grid;
  gap: 1rem;
}

.project-card__lead {
  margin: 0;
  max-width: 52ch;
  font-size: 1.05rem;
  color: var(--text-soft);
}

.project-card__featured-points {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem;
  margin-top: 0.35rem;
}

.project-card__point {
  padding: 1rem;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(10px);
}

.project-card__point span {
  display: block;
  margin-bottom: 0.35rem;
  color: var(--gold);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.project-card__point strong {
  display: block;
  color: var(--text);
  line-height: 1.35;
}

.project-card__hero-visual {
  margin: 0;
  min-height: 420px;
  border-radius: 28px;
  overflow: hidden;
  border: 1px solid rgba(255, 209, 102, 0.18);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.01)),
    linear-gradient(145deg, rgba(12, 18, 32, 0.96), rgba(24, 16, 38, 0.88));
  box-shadow: 0 28px 60px rgba(0, 0, 0, 0.32);
  transform: rotate(1.2deg);
}

.project-card__hero-visual img {
  width: 100%;
  height: 100%;
  min-height: 420px;
  object-fit: contain;
  object-position: center top;
  display: block;
  background: rgba(8, 12, 22, 0.88);
}

.project-card--featured {
  background:
    radial-gradient(circle at top right, rgba(255, 209, 102, 0.14), transparent 24%),
    radial-gradient(circle at bottom left, rgba(0, 245, 212, 0.08), transparent 28%),
    linear-gradient(135deg, rgba(255, 123, 141, 0.06), rgba(255, 255, 255, 0.03) 36%, rgba(0, 245, 212, 0.06));
  border-color: rgba(255, 209, 102, 0.18);
}

.project-card--featured::before {
  opacity: 1;
  background:
    linear-gradient(135deg, rgba(255, 209, 102, 0.08), transparent 22%, rgba(0, 245, 212, 0.06)),
    linear-gradient(180deg, transparent, rgba(255, 255, 255, 0.025));
}

.project-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 0.9rem;
}

.project-card__content {
  display: grid;
  gap: 1rem;
}

.project-card section {
  padding: 1rem 0;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.project-card section:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.project-card h4 {
  margin-bottom: 0.55rem;
  font-size: 1rem;
  color: var(--text);
}

.gallery-grid figure {
  margin: 0;
  overflow: hidden;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.gallery-grid img {
  width: 100%;
  height: 210px;
  object-fit: cover;
  transition: transform 0.7s ease, filter 0.35s ease;
}

.gallery-grid figcaption {
  padding: 0.8rem 1rem 1rem;
  color: var(--text-soft);
  font-size: 0.92rem;
}

.gallery-grid figure:hover {
  transform: translateY(-8px) rotate(-0.4deg);
  border-color: rgba(156, 140, 255, 0.24);
  box-shadow: 0 24px 46px rgba(0, 0, 0, 0.3);
}

.gallery-grid figure:hover img {
  transform: scale(1.04);
  filter: saturate(1.08);
}

.gallery-grid--featured {
  grid-template-columns: minmax(0, 1fr);
}

.gallery-grid--featured figure {
  border-radius: 24px;
}

.gallery-grid--featured img {
  height: 520px;
  object-position: center top;
}

.competency-card {
  border-radius: 22px;
  padding: 1.35rem;
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
  position: relative;
  overflow: hidden;
}

.competency-card h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.cv-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
  gap: 1.5rem;
  align-items: start;
}

.cv-panel--accent {
  background: linear-gradient(135deg, rgba(0, 245, 212, 0.12), rgba(156, 140, 255, 0.12));
}

.cv-heading {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: start;
  margin-bottom: 1rem;
}

.cv-block + .cv-block {
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.cv-item + .cv-item {
  margin-top: 1rem;
}

.cv-item__meta {
  color: var(--cyan);
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 0.35rem;
}

.cv-download {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin-top: 1.4rem;
}

.cv-preview {
  display: grid;
  grid-template-columns: minmax(260px, 0.8fr) minmax(0, 1.6fr);
  gap: 1.5rem;
  align-items: start;
}

.cv-preview__info {
  display: grid;
  gap: 1rem;
}

.cv-preview__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin-top: 0.25rem;
}

.cv-preview__viewer-panel {
  display: grid;
  gap: 1rem;
}

.cv-preview__viewer-shell {
  min-height: 780px;
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02)),
    rgba(3, 8, 16, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.cv-preview__viewer {
  width: 100%;
  height: 780px;
  border: 0;
  display: block;
  background: #ffffff;
}

.cv-preview__fallback {
  margin: 0;
  font-size: 0.94rem;
  color: var(--text-muted);
}

.cv-preview__fallback a {
  color: var(--cyan);
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1.8rem;
}

.stat-card {
  padding: 1.2rem;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.07);
  transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
}

.stat-card:hover {
  transform: translateY(-8px) scale(1.02);
  border-color: rgba(0, 245, 212, 0.2);
  box-shadow: 0 22px 40px rgba(0, 0, 0, 0.24);
}

.stat-card strong,
.meta-pill strong {
  background: var(--title-gradient);
  background-size: 180% auto;
  -webkit-background-clip: text;
  background-clip: text;
  animation: titleSheen 8s linear infinite;
}

.hero__welcome,
.meta-pill,
.stat-card,
.skill-group li,
.tag,
.footer__badge,
.badge {
  backdrop-filter: blur(10px);
}

.stat-card strong {
  display: block;
  font-size: 1.85rem;
  letter-spacing: -0.05em;
  margin-bottom: 0.35rem;
}

.site-footer {
  padding: 2rem 0 2.4rem;
  border-top: 1px solid var(--border);
  background: rgba(7, 11, 20, 0.7);
}

.site-footer__inner {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
}

.site-footer__links {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  color: var(--text-soft);
}

.site-footer p {
  margin: 0;
  color: var(--text-muted);
}

.footer {
  position: relative;
  overflow: hidden;
  background: var(--footer-bg);
  border-top: 1px solid var(--border);
  padding-top: 5rem;
}

.footer::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--footer-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--footer-grid) 1px, transparent 1px);
  background-size: 40px 40px;
  mask-image: radial-gradient(circle at center, black 20%, transparent 90%);
  opacity: 0.4;
  pointer-events: none;
}

.footer::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-gradient);
  opacity: 0.55;
}

.footer__glow-1,
.footer__glow-2 {
  display: none;
}

.footer__main {
  display: grid;
  grid-template-columns: 1.7fr 1fr 1fr 1.1fr;
  gap: 3rem;
  padding-bottom: 3.5rem;
  border-bottom: 1px solid var(--border);
  position: relative;
  z-index: 1;
}

.footer__brand-logo {
  display: block;
  font-size: 2.2rem;
  font-weight: 800;
  letter-spacing: -0.05em;
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 1rem;
}

.footer__brand-tagline {
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.footer__brand-desc {
  max-width: 320px;
  margin-bottom: 1.4rem;
}

.footer__socials {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.footer__social-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  width: fit-content;
  padding: 0.65rem 1rem;
  border-radius: var(--radius-small);
  background: var(--bg-card-strong);
  border: 1px solid var(--border);
  color: var(--text-soft);
  transition: border-color 0.25s ease, background 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease;
}

.footer__social-btn:hover {
  transform: translateX(4px);
  box-shadow: 0 16px 28px rgba(0, 0, 0, 0.22);
}

.footer__social-btn svg {
  transition: transform 0.22s ease;
}

.footer__social-btn:hover svg {
  transform: scale(1.14) rotate(-6deg);
}

.footer__social-btn--linkedin:hover {
  border-color: rgba(156, 140, 255, 0.35);
  background: rgba(156, 140, 255, 0.08);
  color: var(--violet);
}

.footer__social-btn--email:hover {
  border-color: rgba(255, 123, 141, 0.35);
  background: rgba(255, 123, 141, 0.08);
  color: var(--rose);
}

.footer__social-btn--labeled:not(.footer__social-btn--linkedin):not(.footer__social-btn--email):hover {
  border-color: rgba(0, 245, 212, 0.35);
  background: rgba(0, 245, 212, 0.08);
  color: var(--cyan);
}

.footer__col-title {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 1.4rem;
}

.footer__col ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer__col ul a {
  color: var(--text-soft);
  transition: color 0.2s ease, padding-left 0.2s ease;
}

.footer__col ul a:hover {
  color: var(--cyan);
  padding-left: 5px;
}

.footer__available {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  background: rgba(68, 215, 168, 0.08);
  border: 1px solid rgba(68, 215, 168, 0.25);
  border-radius: 14px;
  padding: 0.8rem 1rem;
  margin-bottom: 1.2rem;
}

.footer__available-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 0 rgba(68, 215, 168, 0.5);
  animation: footerPulse 2.2s ease-in-out infinite;
}

@keyframes footerPulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(68, 215, 168, 0.5);
  }
  50% {
    box-shadow: 0 0 0 9px rgba(68, 215, 168, 0);
  }
}

.footer__available-text {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--green);
}

.footer__contact-item {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  padding: 0.7rem 0;
  border-bottom: 1px solid var(--border);
}

.footer__contact-item:last-child {
  border-bottom: 0;
}

.footer__contact-label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.footer__contact-value {
  color: var(--text-soft);
}

.footer__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  padding: 2rem 0;
  position: relative;
  z-index: 1;
}

.footer__copy {
  font-size: 0.92rem;
  color: var(--text-muted);
}

.footer__badges {
  display: flex;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.footer__badge {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.74rem;
  font-weight: 600;
  line-height: 1.1;
  padding: 0.45rem 0.8rem;
  border-radius: 999px;
  overflow: hidden;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.footer__badge:hover {
  transform: none;
}

.badge {
  position: relative;
  overflow: hidden;
}

.badge::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.16), transparent);
  transform: translateX(-120%);
  transition: transform 0.55s ease;
}

.badge:hover::after {
  transform: translateX(120%);
}

.reveal {
  opacity: 0;
  transform: translateY(22px) scale(0.98);
  transition: opacity 0.6s ease, transform 0.6s ease, filter 0.6s ease;
  filter: blur(8px);
}

.reveal.is-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
  filter: blur(0);
}

.panel,
.card,
.project-quicklink,
.project-card,
.competency-card,
.cv-panel,
.feature-card,
.skill-group,
.timeline-card,
.stat-card,
.hero-card,
.gallery-grid figure {
  will-change: transform;
}

.footer__badge--cyan {
  color: var(--cyan);
  background: rgba(0, 245, 212, 0.1);
  border: 1px solid rgba(0, 245, 212, 0.22);
}

.footer__badge--violet {
  color: var(--violet);
  background: rgba(156, 140, 255, 0.1);
  border: 1px solid rgba(156, 140, 255, 0.22);
}

.footer__badge--rose {
  color: var(--rose);
  background: rgba(255, 123, 141, 0.1);
  border: 1px solid rgba(255, 123, 141, 0.22);
}

.muted {
  color: var(--text-muted);
}

/* Floating particles effect */
.hero::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  background-image: 
    radial-gradient(circle at 20% 30%, rgba(0, 245, 212, 0.15) 1px, transparent 1px),
    radial-gradient(circle at 60% 70%, rgba(156, 140, 255, 0.15) 1px, transparent 1px),
    radial-gradient(circle at 80% 20%, rgba(255, 123, 141, 0.15) 1px, transparent 1px);
  background-size: 50px 50px, 80px 80px, 100px 100px;
  animation: particleFloat 20s linear infinite;
  pointer-events: none;
  opacity: 0.4;
  z-index: 0;
}

@keyframes particleFloat {
  0% {
    transform: translateY(0);
  }
  100% {
    transform: translateY(-50px);
  }
}

/* Text glow effect on hover */
.hero__content h1:hover,
.page-hero__content h1:hover {
  text-shadow: 
    0 0 20px rgba(0, 245, 212, 0.6),
    0 0 40px rgba(0, 245, 212, 0.4),
    0 0 60px rgba(0, 245, 212, 0.2);
  transition: text-shadow 0.3s ease;
}

/* Ripple effect for stats cards */
.stat-card {
  position: relative;
  overflow: hidden;
}

.stat-card::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0, 245, 212, 0.3), transparent);
  transform: translate(-50%, -50%);
  transition: width 0.6s ease, height 0.6s ease;
}

.stat-card:hover::before {
  width: 300px;
  height: 300px;
}

/* Smooth color transition for links */
.link-arrow::after {
  content: "→";
  display: inline-block;
  margin-left: 0.5rem;
  transition: transform 0.3s ease, margin-left 0.3s ease;
}

.link-arrow:hover::after {
  transform: translateX(5px);
  margin-left: 0.8rem;
}

/* Skill group animation */
.skill-group li {
  transition: transform 0.2s ease, color 0.2s ease;
}

.skill-group:hover li {
  opacity: 0.5;
}

.skill-group li:hover {
  transform: translateX(10px) scale(1.05);
  opacity: 1 !important;
  color: var(--cyan);
}

/* Hero card photo interaction removed to avoid scroll/overlay problems */
.hero-card__photo {
  overflow: hidden;
  border-radius: 18px;
}

.hero-card__photo img {
  transition: filter 0.2s ease;
}

/* No hover scale/zoom - keeps layout stable */
.hero-card:hover .hero-card__photo img {
  transform: none;
  filter: none;
}

/* Eyebrow pulse animation */
.eyebrow::before {
  animation: eyebrowPulse 2s ease-in-out infinite;
}

@keyframes eyebrowPulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* Footer social button icons rotate */
.footer__social-btn:hover svg {
  animation: iconSpin 0.6s ease;
}

@keyframes iconSpin {
  0% {
    transform: scale(1) rotate(0deg);
  }
  50% {
    transform: scale(1.14) rotate(180deg);
  }
  100% {
    transform: scale(1.14) rotate(360deg);
  }
}

@media (max-width: 980px) {
  .hero__inner,
  .page-hero__inner,
  .cv-layout,
  .cv-preview,
  .grid-two,
  .details-grid,
  .cv-grid {
    grid-template-columns: 1fr;
  }

  .grid-three,
  .skills-grid,
  .projects-overview,
  .competency-grid,
  .gallery-grid,
  .hobby-grid,
  .contact-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .hero-card {
    max-width: 460px;
  }

  .footer__main {
    grid-template-columns: 1fr 1fr;
    gap: 2.5rem;
  }

  .project-card__hero {
    grid-template-columns: 1fr;
  }

  .chez-showcase__intro,
  .chez-showcase__stage,
  .chez-showcase__reflection {
    grid-template-columns: 1fr;
  }

  .chez-showcase__workflow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .project-card__featured-points {
    grid-template-columns: 1fr;
  }

  .project-card__hero-visual,
  .project-card__hero-visual img {
    min-height: 300px;
    transform: none;
  }

  .gallery-grid--featured img {
    height: 360px;
  }
}

@media (max-width: 760px) {
  :root {
    --nav-height: 82px;
  }

  .container {
    width: min(var(--max-width), calc(100% - 1.25rem));
  }

  .nav {
    gap: 0.75rem;
  }

  .nav > nav {
    margin-left: 0;
  }

  .brand {
    min-width: 0;
    gap: 0.7rem;
  }

  .brand__mark {
    min-width: 48px;
    height: 38px;
    padding: 0 0.55rem;
    font-size: 0.9rem;
  }

  .brand__name {
    font-size: 0.9rem;
  }

  .brand__role {
    font-size: 0.68rem;
  }

  .nav__toggle {
    display: block;
    flex-shrink: 0;
  }

  .theme-toggle {
    padding-inline: 0.55rem;
  }

  .theme-toggle__text {
    display: none;
  }

  .nav__links {
    position: fixed;
    inset: var(--nav-height) 1rem auto 1rem;
    display: none;
    flex-direction: column;
    align-items: stretch;
    gap: 0.2rem;
    padding: 0.75rem;
    border-radius: 20px;
    border: 1px solid var(--border);
    background: var(--mobile-menu-bg);
    box-shadow: var(--shadow);
  }

  .nav__links.is-open {
    display: flex;
  }

  .nav__link {
    padding: 0.8rem 0.9rem;
    border-radius: 12px;
  }

  .nav__link::after {
    display: none;
  }

  .nav__link:hover,
  .nav__link[aria-current="page"] {
    background: var(--nav-link-hover-bg);
  }

  .section {
    padding: 4rem 0;
  }

  .hero {
    padding-top: 0.4rem;
  }

  .hero__inner,
  .page-hero__inner {
    gap: 1.4rem;
    padding-block: 2.6rem 2.2rem;
  }

  .hero__content h1,
  .page-hero__content h1 {
    font-size: clamp(2.5rem, 10vw, 4rem);
  }

  .hero__content,
  .page-hero__content {
    gap: 1rem;
  }

  .hero__actions,
  .cv-download,
  .cv-preview__actions {
    flex-direction: column;
    align-items: stretch;
  }

  .hero__actions .btn,
  .cv-download .btn,
  .cv-download a,
  .cv-preview__actions .btn,
  .cv-preview__actions a {
    width: 100%;
    justify-content: center;
  }

  .cv-preview__viewer-shell,
  .cv-preview__viewer {
    min-height: 620px;
    height: 620px;
  }

  .hero-card,
  .project-card,
  .feature-card,
  .cv-panel,
  .timeline-card,
  .project-quicklink,
  .skill-group,
  .competency-card {
    padding: 1.2rem;
  }

  .hero-card {
    max-width: none;
  }

  .hero-card__meta {
    grid-template-columns: 1fr;
  }

  .meta-pill {
    min-width: 0;
  }

  .project-card {
    border-radius: 22px;
  }

  .chez-showcase {
    border-radius: 22px;
  }

  .chez-showcase__visual,
  .chez-showcase__visual img {
    min-height: 330px;
  }

  .chez-showcase__pin {
    position: static;
    margin: 0.6rem 0 0 0.6rem;
  }

  .chez-showcase__workflow {
    grid-template-columns: 1fr;
  }

  .chez-showcase__workflow section {
    min-height: 0;
  }

  .stats-row,
  .grid-three,
  .skills-grid,
  .projects-overview,
  .competency-grid,
  .gallery-grid,
  .hobby-grid,
  .contact-grid {
    grid-template-columns: 1fr;
  }

  .project-card__header,
  .cv-heading,
  .site-footer__inner {
    flex-direction: column;
    align-items: start;
  }

  .project-card__meta,
  .cv-item__meta {
    gap: 0.45rem;
  }

  .gallery-grid img {
    height: 190px;
  }

  .gallery-grid--featured img {
    height: 260px;
  }

  .footer__main,
  .footer__bottom,
  .site-footer__inner {
    gap: 1rem;
  }

  .footer__main {
    grid-template-columns: 1fr;
  }

  .footer__bottom {
    flex-direction: column;
    align-items: start;
  }
}

@media (max-width: 480px) {
  .container {
    width: min(var(--max-width), calc(100% - 1rem));
  }

  .section {
    padding: 3.25rem 0;
  }

  .nav {
    gap: 0.5rem;
  }

  .brand__text {
    min-width: 0;
  }

  .brand__name,
  .brand__role {
    white-space: normal;
  }

  .nav__links {
    inset-inline: 0.5rem;
  }

  .hero__inner,
  .page-hero__inner {
    padding-block: 2.2rem 1.9rem;
  }

  .hero__content h1,
  .page-hero__content h1 {
    font-size: clamp(2.15rem, 12vw, 3rem);
  }

  .section-header h2 {
    font-size: clamp(1.8rem, 8vw, 2.3rem);
  }

  .hero-card,
  .project-card,
  .feature-card,
  .cv-panel,
  .timeline-card,
  .project-quicklink,
  .skill-group,
  .competency-card,
  .stat-card {
    padding: 1rem;
  }

  .badge,
  .tag,
  .skill-group li {
    white-space: normal;
    text-align: center;
    justify-content: center;
  }

  .gallery-grid img {
    height: 170px;
  }

  .stat-card strong {
    font-size: 1.55rem;
  }




}
